import React, { useState, useEffect } from 'react';
import { supabase, TABLE_NAME } from '../supabaseClient';
import { Registration } from '../types';
import { Download, Trash2, LogOut, Search, RefreshCw, AlertTriangle, FileSpreadsheet } from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [registrations, setRegistrations] = useState<Registration[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [deletingAll, setDeletingAll] = useState(false);

  const fetchRegistrations = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from(TABLE_NAME)
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setRegistrations(data || []);
    } catch (err: any) {
      console.error('Error fetching:', err);
      alert('Erro ao carregar dados: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRegistrations();
  }, []);

  const deleteOne = async (id: string) => {
    if (!window.confirm('Tem certeza que deseja deletar este cadastro?')) return;

    try {
      const { error } = await supabase.from(TABLE_NAME).delete().eq('id', id);
      if (error) throw error;
      setRegistrations(prev => prev.filter(r => r.id !== id));
    } catch (err: any) {
      alert('Erro ao deletar: ' + err.message);
    }
  };

  const deleteAll = async () => {
    if (!window.confirm('ATENÇÃO: Deseja realmente deletar TODOS os cadastros? Esta ação não pode ser desfeita.')) return;

    setDeletingAll(true);
    try {
      // Supabase doesn't support bulk delete without where unless configured, 
      // so we use a broad match or multiple calls if needed.
      const { error } = await supabase.from(TABLE_NAME).delete().neq('group_name', 'DO_NOT_EXIST');
      if (error) throw error;
      setRegistrations([]);
      alert('Todos os cadastros foram removidos.');
    } catch (err: any) {
      alert('Erro ao deletar todos: ' + err.message);
    } finally {
      setDeletingAll(false);
    }
  };

  const exportToExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(registrations);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Inscrições K-Pop");

    // Generate buffer and save
    XLSX.writeFile(workbook, `Inscricoes_KPOP_${new Date().toLocaleDateString()}.xlsx`);
  };

  const filteredRegistrations = registrations.filter(r => 
    r.group_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.whatsapp.includes(searchTerm)
  );

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      {/* Sidebar / Top Nav */}
      <nav className="bg-slate-900 text-white p-4 sticky top-0 z-40 shadow-md">
        <div className="container mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4">
            <img 
              src="https://geekzada.com.br/wp-content/uploads/elementor/thumbs/logo-Geekzada26-1-ri1ioubbp1dybect7ciboteekxwmsenbfzooro2k4o.png" 
              alt="Logo" 
              className="h-10 brightness-0 invert"
            />
            <h1 className="font-bold text-lg hidden sm:block">Painel de Controle</h1>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <div className="relative flex-1 md:w-64">
              <Search className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
              <input 
                type="text" 
                placeholder="Buscar grupo, email..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-800 border-none rounded-lg pl-9 pr-4 py-2 text-sm text-white focus:ring-2 focus:ring-purple-500 outline-none"
              />
            </div>
            <button 
              onClick={onLogout}
              className="bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white p-2 rounded-lg transition-all"
              title="Sair"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">
        {/* Header Actions */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
          <div>
            <h2 className="text-2xl font-bold text-slate-800">Inscrições Recebidas</h2>
            <p className="text-slate-500">Total: {registrations.length} cadastros</p>
          </div>

          <div className="flex flex-wrap gap-2 w-full md:w-auto">
            <button 
              onClick={fetchRegistrations}
              className="bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg hover:bg-slate-50 transition flex items-center gap-2 text-sm font-medium"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              Atualizar
            </button>
            <button 
              disabled={registrations.length === 0}
              onClick={exportToExcel}
              className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg shadow-sm transition flex items-center gap-2 text-sm font-medium disabled:opacity-50"
            >
              <FileSpreadsheet className="w-4 h-4" />
              Exportar Excel
            </button>
            <button 
              disabled={registrations.length === 0 || deletingAll}
              onClick={deleteAll}
              className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg shadow-sm transition flex items-center gap-2 text-sm font-medium disabled:opacity-50"
            >
              <Trash2 className="w-4 h-4" />
              Deletar Todos
            </button>
          </div>
        </div>

        {/* Data Table */}
        <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Grupo/Artista</th>
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Categoria</th>
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Música</th>
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Contato</th>
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Data</th>
                  <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {loading ? (
                  <tr>
                    <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                      <div className="flex flex-col items-center gap-2">
                        <RefreshCw className="w-8 h-8 animate-spin text-purple-500" />
                        Carregando inscrições...
                      </div>
                    </td>
                  </tr>
                ) : filteredRegistrations.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="px-6 py-12 text-center text-slate-400">
                      Nenhuma inscrição encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredRegistrations.map((reg) => (
                    <tr key={reg.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="font-bold text-slate-900">{reg.group_name}</div>
                        <div className="text-xs text-slate-500">{reg.city_state}</div>
                      </td>
                      <td className="px-6 py-4 uppercase text-xs font-semibold">
                        <span className={`px-2 py-1 rounded-full ${
                          reg.category === 'solo' ? 'bg-blue-100 text-blue-700' :
                          reg.category === 'duo' ? 'bg-purple-100 text-purple-700' :
                          'bg-pink-100 text-pink-700'
                        }`}>
                          {reg.category}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-sm">{reg.song_artist}</div>
                        <div className="text-xs text-slate-400">{reg.performance_style}</div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium">{reg.whatsapp}</div>
                        <div className="text-xs text-slate-400">{reg.email}</div>
                      </td>
                      <td className="px-6 py-4 text-xs text-slate-500">
                        {new Date(reg.created_at).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button 
                          onClick={() => deleteOne(reg.id!)}
                          className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                        >
                          <Trash2 className="w-5 h-5" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      <footer className="py-8 text-center text-slate-400 text-xs">
        Painel Administrativo Geekzada v1.0
      </footer>
    </div>
  );
};

export default AdminDashboard;

