                      <div className="text-xs text-slate-500 font-medium">
                        {item.character_name || item.song_artist || '-'}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-xs px-2 py-1 rounded bg-slate-800 border border-white/5 text-slate-300 capitalize">
                        {item.category}
                      </span>
