interface LandingPageProps {
  activeContest: ContestType;
  setActiveContest: (type: ContestType) => void;
  onGoAdmin: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ activeContest, setActiveContest, onGoAdmin }) => {
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otherId, setOtherId] = useState('');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const formData = new FormData(e.currentTarget);
    const rawData = Object.fromEntries(formData.entries());

    const data: any = { ...rawData };

    // Tratamento para campo Arena Gamer
    if (activeContest === 'arena' && data.identification === 'Outro:') {
      data.identification = `Outro: ${otherId}`;
    }

    const checkboxes = ['image_release', 'rules_agreement'];

    if (activeContest !== 'kpop' && activeContest !== 'arena') {
      checkboxes.push('authorship_declaration');
    }

    checkboxes.forEach(cb => {
      if (rawData[cb] !== undefined) {
        data[cb] = rawData[cb] === 'on';
      }
    });

    data.created_at = new Date().toISOString();

    const tableName = activeContest === 'kpop' ? TABLES.KPOP : 
                     activeContest === 'cospobre' ? TABLES.COSPOBRE : 
                     activeContest === 'arena' ? TABLES.ARENA :
                     TABLES.COSPLAYER;

    try {
      const { error: insertError } = await supabase.from(tableName).insert([data]);
      if (insertError) throw insertError;
      setSubmitted(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      console.error("Erro ao inserir:", err);
