import React, { useState, useEffect } from 'react';
import { supabase, TABLES } from '../supabaseClient';
import { ContestType } from '../types';
import { Trash2, LogOut, Search, RefreshCw, FileSpreadsheet, Layers, Music, Wand2, Camera, Link, Copy, Check, ExternalLink, Gamepad2 } from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<ContestType>('kpop');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [copiedLink, setCopiedLink] = useState<string | null>(null);

  const menuItems: { id: ContestType; label: string; icon: React.ReactNode; color: string }[] = [
    { id: 'kpop', label: 'K-Pop', icon: <Music className="w-4 h-4" />, color: 'pink' },
    { id: 'cospobre', label: 'Cospobre', icon: <Wand2 className="w-4 h-4" />, color: 'green' },
    { id: 'cosplayer', label: 'Cosplayer', icon: <Camera className="w-4 h-4" />, color: 'purple' },
    { id: 'arena', label: 'Arena Gamer', icon: <Gamepad2 className="w-4 h-4" />, color: 'cyan' }
  ];

  const fetchData = async () => {
    setLoading(true);
    const tableName = activeTab === 'kpop' ? TABLES.KPOP : 
                     activeTab === 'cospobre' ? TABLES.COSPOBRE : 
                     activeTab === 'arena' ? TABLES.ARENA :
                     TABLES.COSPLAYER;
    try {
      const { data: result, error } = await supabase.from(tableName).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setData(result || []);
    } catch (err) {
      console.error(err);
      alert('Erro ao carregar dados do banco.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const deleteOne = async (id: string) => {
    if (!window.confirm('Excluir este registro permanentemente?')) return;
    const tableName = activeTab === 'kpop' ? TABLES.KPOP : activeTab === 'cospobre' ? TABLES.COSPOBRE : activeTab === 'arena' ? TABLES.ARENA : TABLES.COSPLAYER;
    const { error } = await supabase.from(tableName).delete().eq('id', id);
    if (!error) setData(prev => prev.filter(item => item.id !== id));
  };

  const deleteAll = async () => {
    if (!window.confirm('ATENÇÃO: Isso excluirá TODOS os registros desta categoria. Continuar?')) return;
    const tableName = activeTab === 'kpop' ? TABLES.KPOP : activeTab === 'cospobre' ? TABLES.COSPOBRE : activeTab === 'arena' ? TABLES.ARENA : TABLES.COSPLAYER;
    const { error } = await supabase.from(tableName).delete().neq('id', '0');
    if (!error) setData([]);
  };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, activeTab.toUpperCase());
    XLSX.writeFile(wb, `Inscricoes_${activeTab}_2026.xlsx`);
  };

  const handleCopyLink = (type: ContestType) => {
    const baseUrl = window.location.origin + window.location.pathname;
    const hash = type === 'kpop' ? '' : `#${type}`;
    const fullUrl = baseUrl + hash;

    navigator.clipboard.writeText(fullUrl).then(() => {
      setCopiedLink(type);
      setTimeout(() => setCopiedLink(null), 2000);
    });
  };

  const filtered = data.filter(item => 
    JSON.stringify(item).toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans pb-20">
      <nav className="bg-slate-900 border-b border-white/5 p-4 sticky top-0 z-50 shadow-xl">
        <div className="container mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <Layers className="text-pink-500 w-6 h-6" />
            <h1 className="font-black text-xl uppercase tracking-tighter">Admin Geekzada</h1>
          </div>
          <button 
            onClick={onLogout} 
            className="flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-800 hover:bg-red-600/20 hover:text-red-400 text-slate-400 transition-all border border-white/5"
          >
            <span className="text-sm font-bold">SAIR</span>
            <LogOut className="w-4 h-4" />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">

        {/* Seção de Links de Inscrição */}
        <div className="mb-10">
          <div className="flex items-center gap-2 mb-6 text-slate-400">
            <Link className="w-4 h-4" />
            <h2 className="text-xs font-bold uppercase tracking-[0.2em]">Links Rápidos de Inscrição</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {menuItems.map((item) => {
              const hash = item.id === 'kpop' ? '' : `#${item.id}`;
              const fullUrl = window.location.origin + window.location.pathname + hash;
              return (
                <div key={`link-${item.id}`} className="bg-slate-900/50 border border-white/5 rounded-xl p-4 flex flex-col gap-3 group hover:border-white/10 transition-all">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className={`p-2 rounded-lg bg-${item.color}-500/10 text-${item.color}-500`}>
                        {item.icon}
                      </div>
                      <span className="text-sm font-bold text-white uppercase tracking-tight">{item.label}</span>
                    </div>
                    <a href={hash || '/'} target="_blank" rel="noreferrer" className="text-slate-500 hover:text-white transition-colors">
                      <ExternalLink className="w-4 h-4" />
                    </a>
                  </div>
                  <div className="bg-slate-950/50 rounded-lg p-2 flex items-center justify-between gap-2 border border-white/5">
                    <span className="text-[10px] text-slate-500 truncate font-mono">{fullUrl}</span>
                    <button 
                      onClick={() => handleCopyLink(item.id)}
                      className={`p-1.5 rounded transition-all ${copiedLink === item.id ? 'text-green-500 bg-green-500/10' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    >
                      {copiedLink === item.id ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="flex flex-col md:flex-row gap-6 mb-8 items-center justify-between pt-8 border-t border-white/5">
          {/* Seletor de Tabelas */}
          <div className="flex flex-wrap items-center bg-slate-900 p-1 rounded-full border border-white/5 shadow-inner">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`flex items-center gap-2 px-6 py-2 rounded-full text-sm font-bold transition-all ${
                  activeTab === item.id 
                    ? 'bg-pink-600 text-white shadow-lg shadow-pink-500/20' 
                    : 'text-slate-500 hover:text-white hover:bg-white/5'
                }`}
              >
                {item.icon}
                {item.label.toUpperCase()}
              </button>
            ))}
          </div>

          <div className="flex gap-2 w-full md:w-auto">
            <div className="relative flex-1 md:w-64">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-500" />
              <input 
                placeholder="Buscar em qualquer campo..."
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full bg-slate-900 border border-white/5 rounded-lg pl-10 pr-4 py-2 text-sm outline-none focus:ring-1 focus:ring-pink-500"
              />
            </div>
            <button onClick={exportExcel} className="bg-green-600 hover:bg-green-700 p-2.5 rounded-lg transition-colors flex items-center gap-2" title="Exportar para Excel">
              <FileSpreadsheet className="w-5 h-5" />
            </button>
            <button onClick={deleteAll} className="bg-red-600 hover:bg-red-700 p-2.5 rounded-lg transition-colors flex items-center gap-2" title="Excluir Todos os Registros">
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </div>

        <div className="bg-slate-900 rounded-2xl border border-white/5 overflow-hidden shadow-2xl">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white/5 text-slate-400 text-[10px] uppercase font-bold tracking-widest">
                  <th className="px-6 py-4">Inscrito / Grupo</th>
                  <th className="px-6 py-4">{activeTab === 'arena' ? 'Identificação' : 'Categoria'}</th>
                  <th className="px-6 py-4">WhatsApp</th>
                  <th className="px-6 py-4">Data Inscrição</th>
                  <th className="px-6 py-4 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {loading ? (
                  <tr><td colSpan={5} className="p-32 text-center"><RefreshCw className="animate-spin mx-auto w-12 h-12 text-pink-500" /></td></tr>
                ) : filtered.length === 0 ? (
                  <tr><td colSpan={5} className="p-20 text-center text-slate-500 font-medium italic">Nenhum registro encontrado para {activeTab}.</td></tr>
                ) : filtered.map(item => (
                  <tr key={item.id} className="hover:bg-white/[0.02] transition-colors group">
                    <td className="px-6 py-4">
                      <div className="font-bold text-white group-hover:text-pink-400 transition-colors">
                        {item.group_name || item.cosplayer_name || item.full_name || item.name}
                      </div>
                      <div className="text-xs text-slate-500 font-medium">
                        {item.character_name || item.song_artist || item.email || '-'}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-xs px-2 py-1 rounded bg-slate-800 border border-white/5 text-slate-300 capitalize">
                        {item.category || item.identification}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm font-mono text-slate-300">{item.whatsapp}</td>
                    <td className="px-6 py-4 text-xs text-slate-500">{new Date(item.created_at).toLocaleString('pt-BR')}</td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => deleteOne(item.id)} 
                        className="p-2 rounded-lg text-slate-600 hover:bg-red-500/10 hover:text-red-500 transition-all"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>

      <footer className="py-8 text-center text-slate-700 text-xs border-t border-white/5 mt-10 tracking-widest font-bold">
        WD SOLUÇÕES DIGITAIS LTDA 2026
      </footer>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import Header from '../components/Header';
import { supabase, TABLES } from '../supabaseClient';
import { ContestType } from '../types';
import { CheckCircle2, Music, Send, Star, AlertCircle, Camera, Wand2, Gamepad2, MapPin, Calendar } from 'lucide-react';

interface LandingPageProps {
  activeContest: ContestType;
  setActiveContest: (type: ContestType) => void;
  onGoAdmin: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ activeContest, setActiveContest, onGoAdmin }) => {
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otherId, setOtherId] = useState('');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const formData = new FormData(e.currentTarget);
    const rawData = Object.fromEntries(formData.entries());

    const data: any = { ...rawData };

    // Tratamento robusto para campo Arena Gamer "Outro"
    if (activeContest === 'arena') {
      if (data.identification === 'Outro:') {
        data.identification = `Outro: ${otherId || 'Não especificado'}`;
      }
      delete data.other_id; // Remove campo auxiliar do envio
    }

    // Gerenciamento de Checkboxes
    const checkboxFields = ['image_release', 'rules_agreement', 'authorship_declaration'];
    checkboxFields.forEach(field => {
      if (data[field] !== undefined) {
        data[field] = data[field] === 'on';
      }
    });

    data.created_at = new Date().toISOString();

    const tableName = activeContest === 'kpop' ? TABLES.KPOP : 
                     activeContest === 'cospobre' ? TABLES.COSPOBRE : 
                     activeContest === 'arena' ? TABLES.ARENA :
                     TABLES.COSPLAYER;

    try {
      const { error: insertError } = await supabase.from(tableName).insert([data]);
      if (insertError) throw insertError;
      setSubmitted(true);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err: any) {
      console.error("Erro ao inserir:", err);
      setError(err.message || 'Ocorreu um erro ao enviar o cadastro. Verifique sua conexão.');
    } finally {
      setLoading(false);
    }
  };

  const getContestVisuals = (type: ContestType) => {
    switch (type) {
      case 'cospobre': return { title: 'Cospobre', color: 'from-green-500', shadow: 'shadow-green-500/20' };
      case 'cosplayer': return { title: 'Cosplayer', color: 'from-purple-500', shadow: 'shadow-purple-500/20' };
      case 'arena': return { title: 'Arena Gamer', color: 'from-cyan-500', shadow: 'shadow-cyan-500/20' };
      default: return { title: 'K-Pop', color: 'from-pink-500', shadow: 'shadow-pink-500/20' };
    }
  };

  const activeVisuals = getContestVisuals(activeContest);

  const renderFormFields = () => {
    const inputStyle = "w-full bg-slate-800 border border-slate-700 rounded-lg p-3 focus:ring-2 focus:ring-pink-500 outline-none text-white transition-all placeholder:text-slate-600";
    const labelStyle = "text-sm font-medium text-slate-400 mb-1 block";

    if (activeContest === 'arena') {
      return (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome Completo *</label>
              <input required name="name" type="text" className={inputStyle} placeholder="Seu nome" />
            </div>
            <div>
              <label className={labelStyle}>E-mail *</label>
              <input required name="email" type="email" className={inputStyle} placeholder="email@exemplo.com" />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Telefone / WhatsApp *</label>
              <input required name="whatsapp" type="tel" className={inputStyle} placeholder="(00) 00000-0000" />
            </div>
            <div>
              <label className={labelStyle}>Data de Nascimento *</label>
              <input required name="birth_date" type="date" className={inputStyle} />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Bairro *</label>
              <input required name="bairro" type="text" className={inputStyle} placeholder="Seu bairro" />
            </div>
            <div>
              <label className={labelStyle}>Cidade *</label>
              <input required name="city" type="text" className={inputStyle} placeholder="Sua cidade" />
            </div>
          </div>
          <div>
            <label className={labelStyle}>Como você se identifica? *</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-2">
              {['Gamer', 'Otaku', 'Cosplayer', 'K-popper', 'Entusiasta da Cultura Geek', 'Outro:'].map((opt) => (
                <label key={opt} className="flex items-center gap-3 p-3 bg-slate-800/50 border border-slate-700 rounded-lg cursor-pointer hover:bg-slate-800 transition-colors">
                  <input required name="identification" type="radio" value={opt} className="w-4 h-4 text-cyan-500 focus:ring-offset-slate-900" />
                  <span className="text-sm text-slate-300">{opt}</span>
                </label>
              ))}
            </div>
            <input 
              name="other_id" 
              type="text" 
              placeholder="Especifique se escolheu Outro" 
              className={`${inputStyle} mt-3 text-sm h-10`}
              value={otherId}
              onChange={(e) => setOtherId(e.target.value)}
            />
          </div>
        </div>
      );
    }

    if (activeContest === 'kpop') {
      return (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome do grupo ou artista solo *</label>
              <input required name="group_name" type="text" placeholder="Ex: Blackpink Cover" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Categoria *</label>
              <select required name="category" className={inputStyle}>
                <option value="">Selecione...</option>
                <option value="solo">Solo</option>
                <option value="duo">Duo</option>
                <option value="grupo">Grupo</option>
              </select>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome do responsável (se menor)</label>
              <input name="guardian_name" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>CPF ou RG do responsável *</label>
              <input required name="guardian_document" type="text" className={inputStyle} />
            </div>
          </div>
          <div className="space-y-4">
            <label className={labelStyle}>Nome completo dos integrantes *</label>
            <textarea required name="members_names" rows={3} className={inputStyle} placeholder="Liste os nomes separados por vírgula"></textarea>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className={labelStyle}>Idades *</label>
              <input required name="members_ages" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Nascimento principal *</label>
              <input required name="birth_date" type="date" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Qtd no palco *</label>
              <input required name="members_count" type="number" className={inputStyle} />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className={labelStyle}>Estilo *</label>
              <select required name="performance_style" className={inputStyle}>
                <option value="dance cover">Dance Cover</option>
                <option value="vocal">Vocal</option>
                <option value="rap">Rap</option>
              </select>
            </div>
            <div>
              <label className={labelStyle}>Música/Artista *</label>
              <input required name="song_artist" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Duração *</label>
              <input required name="duration" type="text" className={inputStyle} />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome do Fandom</label>
              <input name="fandom_name" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Redes Sociais (Links)</label>
              <input name="social_links" type="text" className={inputStyle} />
            </div>
          </div>
          <div>
            <label className={labelStyle}>Link do vídeo de apresentação *</label>
            <input required name="video_link" type="url" className={inputStyle} placeholder="YouTube ou Drive" />
          </div>
        </>
      );
    }

    if (activeContest === 'cospobre' || activeContest === 'cosplayer') {
      const isCosplayer = activeContest === 'cosplayer';
      return (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>{isCosplayer ? 'Nome completo do cosplayer *' : 'Nome do cosplayer *'}</label>
              <input required name={isCosplayer ? "full_name" : "cosplayer_name"} type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Nome do personagem *</label>
              <input required name="character_name" type="text" className={inputStyle} />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>{isCosplayer ? 'Obra de origem *' : 'Obra do personagem *'}</label>
              <input required name={isCosplayer ? "origin_work" : "character_origin"} type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Categoria *</label>
              <select required name="category" className={inputStyle}>
                <option value="tradicional">Tradicional</option>
                <option value="desfile">Desfile</option>
                <option value="apresentacao">Apresentação</option>
                <option value="kids">Kids</option>
                <option value="grupo">Grupo</option>
              </select>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className={labelStyle}>Tipo de Cosplay *</label>
              <select required name="cosplay_type" className={inputStyle}>
                <option value="original">Original</option>
                <option value="adaptado">Adaptado</option>
                <option value="replica">Réplica</option>
                {isCosplayer && <option value="autorais">Autorais</option>}
              </select>
            </div>
            <div>
              <label className={labelStyle}>Idade *</label>
              <input required name="age" type="number" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Nascimento *</label>
              <input required name="birth_date" type="date" className={inputStyle} />
            </div>
          </div>
          <div>
            <label className={labelStyle}>{isCosplayer ? 'Fotos (Frente, Costas, Detalhes) *' : 'Link de fotos (Drive/Instagram) *'}</label>
            <input required name="photo_links" type="url" className={inputStyle} placeholder="Link da pasta ou perfil" />
          </div>
          <div>
            <label className={labelStyle}>{isCosplayer ? 'Descrição do cosplay e processo de confecção *' : 'Descrição do cosplay (Materiais e criação) *'}</label>
            <textarea required name={isCosplayer ? "description_process" : "cosplay_description"} rows={3} className={inputStyle}></textarea>
          </div>
          <label className="flex items-center gap-3 cursor-pointer group">
            <input name="authorship_declaration" type="checkbox" className="w-5 h-5 rounded border-slate-700 text-pink-500 bg-slate-800" />
            <span className="text-sm text-slate-300">Declaração de autoria do cosplay.</span>
          </label>
        </>
      );
    }
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4 animate-in fade-in zoom-in duration-500 text-center">
        <div className={`bg-slate-900 p-8 rounded-2xl shadow-2xl border border-green-500 max-w-md w-full space-y-6`}>
          <CheckCircle2 className="w-20 h-20 text-green-500 mx-auto" />
          <h2 className="text-3xl font-bold text-white">
            {activeContest === 'arena' ? 'Tudo certo!' : 'Inscrição Realizada!'}
          </h2>
          <p className="text-slate-300">
            {activeContest === 'arena' 
              ? 'Seu nome já está na lista.' 
              : `Seu cadastro para o Concurso ${activeVisuals.title} foi recebido com sucesso.`}
          </p>
          <button onClick={() => setSubmitted(false)} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-lg transition-colors">Voltar</button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-slate-950 min-h-screen text-white pb-20">
      <Header activeContest={activeContest} setActiveContest={setActiveContest} />

      <div className="container mx-auto px-4 pt-12 pb-12 text-center">
        <span className="bg-white/10 text-white px-4 py-1 rounded-full text-sm font-semibold mb-4 inline-block border border-white/10 uppercase tracking-widest">
          EVENTO GEEKZADA 2026
        </span>
        <h2 className={`text-5xl md:text-7xl font-black bg-clip-text text-transparent bg-gradient-to-r ${activeVisuals.color} to-indigo-400 uppercase tracking-tighter mb-4`}>
          {activeContest === 'arena' ? 'Arena Gamer 2026' : `CONCURSO ${activeVisuals.title}`}
        </h2>

        {activeContest === 'arena' ? (
          <div className="space-y-2 mb-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex items-center justify-center gap-4 text-cyan-400 font-bold">
              <div className="flex items-center gap-1"><Calendar className="w-5 h-5" /> 14/Fevereiro | 🕘 09:00</div>
            </div>
            <div className="flex items-center justify-center gap-2 text-slate-400">
              <MapPin className="w-5 h-5" /> Local: Estádio Mangueirão
            </div>
          </div>
        ) : (
          <p className="text-slate-400 max-w-xl mx-auto text-sm md:text-base mb-8">
            Preencha todos os campos abaixo corretamente para garantir sua participação no evento.
          </p>
        )}
      </div>

      <section className="container mx-auto px-4">
        <div className={`max-w-4xl mx-auto bg-slate-900/40 backdrop-blur-xl border border-white/5 rounded-3xl p-6 md:p-10 shadow-2xl transition-all duration-500 ${activeVisuals.shadow}`}>
          <form onSubmit={handleSubmit} className="space-y-8">
            {renderFormFields()}

            {/* Campos comuns para competições (não Arena) */}
            {activeContest !== 'arena' && (
              <div className="space-y-6 pt-6 border-t border-white/5">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="text-sm font-medium text-slate-400 mb-1 block">Cidade e Estado *</label>
                    <input required name="city_state" type="text" className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-pink-500 outline-none" />
                  </div>
                  <div>
                    <label className="text-sm font-medium text-slate-400 mb-1 block">Telefone / WhatsApp *</label>
                    <input required name="whatsapp" type="tel" className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-pink-500 outline-none" />
                  </div>
                </div>
                <div>
                  <label className="text-sm font-medium text-slate-400 mb-1 block">E-mail *</label>
                  <input required name="email" type="email" className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-pink-500 outline-none" />
                </div>
                <div className="space-y-4">
                  <label className="text-sm font-medium text-slate-400 mb-1 block">Necessidades Técnicas</label>
                  <textarea name="technical_needs" rows={2} placeholder="Ex: Microfone sem fio, cabo P10, etc." className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-pink-500 outline-none"></textarea>
                </div>
              </div>
            )}

            <div className="space-y-4 pt-6 border-t border-white/5">
              <label className="flex items-center gap-3 cursor-pointer group">
                <input required name="image_release" type="checkbox" className="w-5 h-5 rounded border-slate-700 text-pink-500 bg-slate-800" />
                <span className="text-sm text-slate-300 group-hover:text-white transition-colors">Autorização de uso de imagem e voz.</span>
              </label>
              <label className="flex items-center gap-3 cursor-pointer group">
                <input required name="rules_agreement" type="checkbox" className="w-5 h-5 rounded border-slate-700 text-pink-500 bg-slate-800" />
                <span className="text-sm text-slate-300 group-hover:text-white transition-colors">Concordo com o regulamento do evento.</span>
              </label>

              {activeContest !== 'arena' && (
                <div>
                  <label className="text-sm font-medium text-slate-400 mb-1 block">Assinatura Digital *</label>
                  <input required name="signature" type="text" placeholder="Nome Completo" className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-pink-500 outline-none" />
