                <AlertCircle className="shrink-0" /> 
                <span className="text-sm">{error}</span>
              </div>
            )}

            <button disabled={loading} type="submit" className={`w-full bg-gradient-to-r ${activeContest === 'arena' ? 'from-cyan-600 to-blue-600 shadow-cyan-500/20' : 'from-pink-600 to-purple-600 shadow-pink-500/20'} hover:opacity-90 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all transform active:scale-[0.98] shadow-xl disabled:opacity-50 disabled:cursor-not-allowed`}>
              {loading ? <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <><Star className="w-5 h-5" /> {activeContest === 'arena' ? 'GARANTIR MEU NOME NA LISTA' : 'FINALIZAR INSCRIÇÃO'}</>}
