                </a>
              </div>
            )}

            <button 
              onClick={() => setSubmitted(false)} 
              className="w-full bg-slate-800 hover:bg-slate-700 text-slate-300 font-black py-4 rounded-2xl transition-all uppercase tracking-widest text-[10px] active:scale-95"
