import React, { useState, useEffect, useCallback } from 'react';
import LandingPage from './pages/LandingPage.tsx';
import AdminLogin from './pages/AdminLogin.tsx';
import AdminDashboard from './pages/AdminDashboard.tsx';
import { AppRoute, ContestType } from './types.ts';

const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.LANDING);
  const [activeContest, setActiveContest] = useState<ContestType>('kpop');

  const handleRouteUpdate = useCallback(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#admin')) {
      const isLoggedIn = sessionStorage.getItem('admin_logged_in') === 'true';
      setCurrentRoute(isLoggedIn ? AppRoute.ADMIN_DASHBOARD : AppRoute.ADMIN_LOGIN);
    } else if (hash === '#cospobre') {
      setActiveContest('cospobre');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#cosplayer') {
      setActiveContest('cosplayer');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#arena') {
      setActiveContest('arena');
      setCurrentRoute(AppRoute.LANDING);
    } else {
      setActiveContest('kpop');
      setCurrentRoute(AppRoute.LANDING);
    }
  }, []);

  useEffect(() => {
    window.addEventListener('hashchange', handleRouteUpdate);
    handleRouteUpdate();

    return () => window.removeEventListener('hashchange', handleRouteUpdate);
  }, [handleRouteUpdate]);

  const navigate = (route: string) => {
    window.location.hash = route;
  };

  const renderContent = () => {
    switch (currentRoute) {
      case AppRoute.ADMIN_LOGIN:
        return (
          <AdminLogin 
            onLogin={() => {
              handleRouteUpdate();
            }} 
          />
        );
      case AppRoute.ADMIN_DASHBOARD:
        return (
          <AdminDashboard 
            onLogout={() => {
              sessionStorage.removeItem('admin_logged_in');
              navigate('');
            }} 
          />
        );
      case AppRoute.LANDING:
      default:
        return (
          <LandingPage 
            activeContest={activeContest} 
            setActiveContest={(type) => navigate(type === 'kpop' ? '' : type)}
            onGoAdmin={() => navigate('admin')} 
          />
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-950">
      {renderContent()}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Header from '../components/Header.tsx';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { CheckCircle2, Music, Send, Star, AlertCircle, Camera, Wand2, Gamepad2, MapPin, Calendar, User, Mail, Phone, Home, Map, RefreshCw, MessageCircle, Award } from 'lucide-react';

interface LandingPageProps {
  activeContest: ContestType;
  setActiveContest: (type: ContestType) => void;
  onGoAdmin: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ activeContest, setActiveContest, onGoAdmin }) => {
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otherId, setOtherId] = useState('');
  const [selectedIdentifications, setSelectedIdentifications] = useState<string[]>([]);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setSelectedIdentifications([]);
    setOtherId('');
    setError(null);
  }, [activeContest]);

  const handleIdentificationChange = (val: string) => {
    if (selectedIdentifications.includes(val)) {
      setSelectedIdentifications(prev => prev.filter(i => i !== val));
    } else {
      if (selectedIdentifications.length < 3) {
        setSelectedIdentifications(prev => [...prev, val]);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (activeContest === 'arena' && selectedIdentifications.length === 0) {
      setError('Selecione pelo menos uma opção em "Como você se identifica?".');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData(e.currentTarget);
    const rawData = Object.fromEntries(formData.entries());

    let payload: any = { ...rawData };
    const createdAt = new Date().toISOString();

    if (activeContest === 'arena') {
      const finalIdentifications = selectedIdentifications.map(item => {
        if (item === 'Outro:') return `Outro: ${otherId || 'Não especificado'}`;
        return item;
      }).join(', ');

      payload = {
        name: rawData.name,
        email: rawData.email,
        whatsapp: rawData.whatsapp,
        bairro: rawData.bairro,
        city: rawData.city,
        birth_date: rawData.birth_date,
        identification: finalIdentifications,
        created_at: createdAt
      };
    } else {
      payload.created_at = createdAt;
      const checkboxFields = ['image_release', 'rules_agreement', 'authorship_declaration'];
      checkboxFields.forEach(field => {
        if (payload[field] !== undefined) {
          payload[field] = payload[field] === 'on';
        }
      });
    }

    const tableName = activeContest === 'kpop' ? TABLES.KPOP : 
                     activeContest === 'cospobre' ? TABLES.COSPOBRE : 
                     activeContest === 'arena' ? TABLES.ARENA :
                     TABLES.COSPLAYER;

    try {
      const { error: insertError } = await supabase.from(tableName).insert([payload]);
      if (insertError) throw insertError;
      setSubmitted(true);
    } catch (err: any) {
      console.error("Erro ao inserir:", err);
      setError(err.message || 'Ocorreu um erro ao processar sua inscrição.');
    } finally {
      setLoading(false);
    }
  };

  const getContestVisuals = (type: ContestType) => {
    switch (type) {
      case 'cospobre': return { title: 'Cospobre', color: 'from-green-500', accent: 'green', shadow: 'shadow-green-500/20', focus: 'focus:ring-green-500/50 focus:border-green-500', btn: 'bg-green-600 hover:bg-green-500' };
