              <div className="mt-8 pt-6 border-t border-white/5 text-right">
                 <p className="text-[10px] text-slate-600 font-bold">INSCRITO EM: {new Date(selectedItem.created_at).toLocaleString('pt-BR')}</p>
              </div>
            </div>
          </div>
        </div>
