          <div className="w-16 h-1 bg-slate-800 mx-auto mb-12 rounded-full"></div>
          <p className="text-slate-800 font-black tracking-[0.5em] text-[10px] mb-8 uppercase">WD SOLUÇÕES DIGITAIS 2026</p>
