              <button onClick={() => setActiveContest('cospobre')} className="text-slate-700 text-[8px] font-bold uppercase tracking-[0.2em] hover:text-white transition-colors">Cospobre</button>
              <button onClick={() => setActiveContest('cosplayer')} className="text-slate-700 text-[8px] font-bold uppercase tracking-[0.2em] hover:text-white transition-colors">Cosplayer</button>
              <button onClick={() => setActiveContest('arena')} className="text-slate-700 text-[8px] font-bold uppercase tracking-[0.2em] hover:text-white transition-colors">Arena</button>
              <button onClick={() => setActiveContest('imprensa')} className="text-slate-700 text-[8px] font-bold uppercase tracking-[0.2em] hover:text-white transition-colors">Imprensa</button>
