import React, { useState, useEffect } from 'react';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  Trash2, LogOut, Search, RefreshCw, FileSpreadsheet, Layers, 
  Music, Wand2, Camera, Link, Copy, Check, ExternalLink, 
  Gamepad2, X, Eye, Calendar, User, Phone, Mail, Info, 
  Share2, TriangleAlert, Mic
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<ContestType>('kpop');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [copiedLink, setCopiedLink] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<any | null>(null);

  const contestConfig: Record<ContestType, { label: string; icon: any; colorClass: string; bgColorClass: string; textColorClass: string; hash: string }> = {
    kpop: { label: 'K-Pop', icon: Music, colorClass: 'bg-pink-600', bgColorClass: 'bg-pink-500/10', textColorClass: 'text-pink-500', hash: '' },
    cospobre: { label: 'Cospobre', icon: Wand2, colorClass: 'bg-green-600', bgColorClass: 'bg-green-500/10', textColorClass: 'text-green-500', hash: '#cospobre' },
    cosplayer: { label: 'Cosplayer', icon: Camera, colorClass: 'bg-purple-600', bgColorClass: 'bg-purple-500/10', textColorClass: 'text-purple-500', hash: '#cosplayer' },
    arena: { label: 'Arena Gamer', icon: Gamepad2, colorClass: 'bg-cyan-600', bgColorClass: 'bg-cyan-500/10', textColorClass: 'text-cyan-500', hash: '#arena' },
    imprensa: { label: 'Imprensa', icon: Mic, colorClass: 'bg-indigo-600', bgColorClass: 'bg-indigo-500/10', textColorClass: 'text-indigo-500', hash: '#imprensa' }
  };

  const menuItems = (Object.keys(contestConfig) as ContestType[]).map(key => ({
    id: key,
    ...contestConfig[key]
  }));

  const fetchData = async () => {
    setLoading(true);
    const tableName = activeTab === 'kpop' ? TABLES.KPOP : 
                     activeTab === 'cospobre' ? TABLES.COSPOBRE : 
                     activeTab === 'arena' ? TABLES.ARENA :
                     activeTab === 'imprensa' ? TABLES.IMPRENSA :
                     TABLES.COSPLAYER;
    try {
      const { data: result, error } = await supabase.from(tableName).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setData(result || []);
    } catch (err) {
      console.error(err);
      alert('Erro ao carregar dados do banco.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const deleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!id) return;

    const confirmMessage = `Tem certeza que deseja excluir permanentemente este registro?`;
    if (!window.confirm(confirmMessage)) return;

    const tableName = activeTab === 'kpop' ? TABLES.KPOP : 
                     activeTab === 'cospobre' ? TABLES.COSPOBRE : 
                     activeTab === 'arena' ? TABLES.ARENA :
                     activeTab === 'imprensa' ? TABLES.IMPRENSA :
                     TABLES.COSPLAYER;

    try {
      const { error } = await supabase.from(tableName).delete().eq('id', id);
      if (error) throw error;
      setData(prev => prev.filter(item => item.id !== id));
      if (selectedItem?.id === id) {
        setSelectedItem(null);
      }
    } catch (err: any) {
      console.error("Erro ao deletar:", err);
      alert('Não foi possível excluir o registro.');
    }
  };

  const deleteAll = async () => {
    if (data.length === 0) return alert('Não há registros para deletar.');
    const count = data.length;
    const confirmation = window.confirm(`⚠️ ALERTA CRÍTICO: Você está prestes a deletar TODOS os ${count} registros da categoria ${activeTab.toUpperCase()}!`);
    if (!confirmation) return;

    setLoading(true);
    const tableName = activeTab === 'kpop' ? TABLES.KPOP : 
                     activeTab === 'cospobre' ? TABLES.COSPOBRE : 
                     activeTab === 'arena' ? TABLES.ARENA :
                     activeTab === 'imprensa' ? TABLES.IMPRENSA :
                     TABLES.COSPLAYER;

    try {
      const { error } = await supabase.from(tableName).delete().neq('id', '00000000-0000-0000-0000-000000000000');
      if (error) throw error;
      setData([]);
      setSelectedItem(null);
    } catch (err: any) {
      console.error(err);
      alert('Erro ao deletar registros.');
    } finally {
      setLoading(false);
    }
  };

  const exportExcel = () => {
    if (data.length === 0) return alert('Não há dados para exportar.');
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, activeTab.toUpperCase());
    XLSX.writeFile(wb, `Geekzada_${activeTab}_2026.xlsx`);
  };

  const copyFormLink = (hash: string, id: string) => {
    const baseUrl = window.location.origin + window.location.pathname;
    const fullUrl = baseUrl + hash;
    navigator.clipboard.writeText(fullUrl);
    setCopiedLink(id);
    setTimeout(() => setCopiedLink(null), 2000);
  };

  const renderMediaPreview = (key: string, value: any) => {
    if (!value || typeof value !== 'string' || !value.startsWith('http')) return null;
    const url = value.trim();
    const isVideoField = key.toLowerCase().includes('video');
    const ytMatch = url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/);
    const driveMatch = url.match(/drive\.google\.com\/file\/d\/([^\/\?]+)/);

    if (isVideoField) {
      if (ytMatch && ytMatch[1]) {
        return (
          <div className="mt-2 aspect-video rounded-xl overflow-hidden border border-white/10 bg-black">
            <iframe className="w-full h-full" src={`https://www.youtube.com/embed/${ytMatch[1]}`} frameBorder="0" allowFullScreen></iframe>
          </div>
        );
      }
    }
    return null;
  };

  const filtered = data.filter(item => 
    JSON.stringify(item).toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans pb-20">
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-white/10 w-full max-w-2xl max-h-[90vh] rounded-[2rem] shadow-2xl overflow-hidden flex flex-col">
            <div className={`p-6 border-b border-white/5 flex items-center justify-between bg-gradient-to-r ${contestConfig[activeTab].colorClass}/10 to-transparent`}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${contestConfig[activeTab].bgColorClass} ${contestConfig[activeTab].textColorClass}`}><Info className="w-5 h-5" /></div>
                <div>
                  <h3 className="font-black text-white uppercase tracking-tight">Detalhes do Registro</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{activeTab === 'imprensa' ? 'CREDENCIAL IMPRENSA' : 'INSCRIÇÃO CONCURSO'}</p>
                </div>
              </div>
              <button onClick={() => setSelectedItem(null)} className="p-2 hover:bg-white/5 rounded-full"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="overflow-y-auto p-8 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-8">
                {Object.entries(selectedItem).map(([key, value]) => {
                  if (key === 'id' || key === 'created_at') return null;
                  return (
                    <div key={key} className="space-y-1">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{key.replace(/_/g, ' ')}</p>
                      <div className="text-sm font-medium text-slate-200 bg-white/5 p-3 rounded-xl border border-white/5 break-words">
                        {typeof value === 'boolean' ? (value ? '✅ Sim' : '❌ Não') : (value?.toString() || '-')}
                        {renderMediaPreview(key, value)}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      <nav className="bg-slate-900 border-b border-white/5 p-4 sticky top-0 z-50">
        <div className="container mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <Layers className="text-pink-500 w-6 h-6" />
            <h1 className="font-black text-xl uppercase tracking-tighter">Admin Geekzada</h1>
          </div>
          <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-800 text-slate-400 border border-white/5 hover:bg-red-600/20">
            <span className="text-sm font-bold">SAIR</span><LogOut className="w-4 h-4" />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">
        <div className="mb-10 bg-slate-900/30 p-6 rounded-[2rem] border border-white/5">
           <div className="flex items-center gap-3 mb-6"><Link className="w-4 h-4 text-pink-500" /><p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">Gerenciamento de Fluxos</p></div>
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
              {menuItems.map((item) => (
                <div key={item.id} className="bg-slate-900/80 border border-white/5 p-4 rounded-2xl flex items-center justify-between group hover:border-pink-500/30 transition-all">
                  <div className="flex items-center gap-3">
                    <div className={`p-2.5 rounded-xl ${item.bgColorClass} ${item.textColorClass}`}><item.icon className="w-4 h-4" /></div>
                    <span className="text-xs font-black uppercase text-slate-100">{item.label}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <a href={`${window.location.origin}${window.location.pathname}${item.hash}`} target="_blank" className="p-2 hover:bg-white/5 rounded-lg text-slate-500"><ExternalLink className="w-4 h-4" /></a>
                    <button onClick={() => copyFormLink(item.hash, item.id)} className="p-2 hover:bg-white/5 rounded-lg text-slate-500">{copiedLink === item.id ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}</button>
                  </div>
                </div>
              ))}
           </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-6 mb-8 items-center justify-between">
          <div className="flex flex-wrap justify-center items-center bg-slate-900 p-1.5 rounded-full border border-white/5">
            {menuItems.map((item) => (
              <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-xs font-black transition-all ${activeTab === item.id ? `${item.colorClass} text-white` : 'text-slate-500 hover:text-white'}`}>
                <item.icon className="w-4 h-4" /><span>{item.label.toUpperCase()}</span>
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 w-full lg:w-auto">
            <input placeholder="Procurar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="flex-1 lg:w-64 bg-slate-900 border border-white/5 rounded-xl px-4 py-2.5 text-sm outline-none" />
            <button onClick={exportExcel} className="bg-green-600 px-4 py-2.5 rounded-xl flex items-center gap-2 text-white font-black uppercase text-xs"><FileSpreadsheet className="w-4 h-4" />Exportar</button>
            <button onClick={deleteAll} className="bg-red-600/10 text-red-500 border border-red-500/20 px-4 py-2.5 rounded-xl flex items-center gap-2 font-black uppercase text-xs"><Trash2 className="w-4 h-4" />Limpar</button>
          </div>
        </div>

        <div className="bg-slate-900/50 rounded-[2.5rem] border border-white/5 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white/5 text-slate-500 text-[10px] uppercase font-black tracking-[0.2em]">
                  <th className="px-8 py-5">{activeTab === 'imprensa' ? 'Nome do Profissional' : 'Nome / Grupo'}</th>
                  <th className="px-8 py-5">{activeTab === 'imprensa' ? 'Veículo / Mídia' : activeTab === 'arena' ? 'Bairro' : 'Categoria'}</th>
                  <th className="px-8 py-5">WhatsApp</th>
                  <th className="px-8 py-5">Status</th>
                  <th className="px-8 py-5 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {loading ? (
                  <tr><td colSpan={5} className="p-32 text-center"><RefreshCw className="animate-spin mx-auto w-10 h-10 text-pink-500" /></td></tr>
                ) : filtered.length === 0 ? (
                  <tr><td colSpan={5} className="p-24 text-center text-slate-500 font-bold uppercase tracking-widest opacity-50">Nenhum registro encontrado</td></tr>
                ) : filtered.map(item => (
                  <tr key={item.id} onClick={() => setSelectedItem(item)} className="hover:bg-white/[0.03] cursor-pointer transition-all group">
                    <td className="px-8 py-5">
                      <div className="font-black text-white group-hover:text-pink-400 transition-colors uppercase tracking-tight">
                        {activeTab === 'imprensa' ? item.full_name : (item.group_name || item.cosplayer_name || item.full_name || item.name)}
                      </div>
                      <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">
                        {activeTab === 'imprensa' ? (item.badge_name || '-') : (item.character_name || item.song_artist || item.email || '-')}
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      {activeTab === 'imprensa' ? (
                        <div className="flex flex-col gap-1">
                          <span className={`text-[10px] font-black px-3 py-1.5 rounded-full border bg-indigo-500/10 text-indigo-500 border-transparent uppercase inline-block w-fit`}>
                            {item.media_outlet || 'Veículo N/A'}
                          </span>
                          <span className="text-[8px] text-slate-500 font-bold ml-2">{item.media_type || '-'}</span>
                        </div>
                      ) : (
                        <span className={`text-[10px] font-black px-3 py-1.5 rounded-full border ${contestConfig[activeTab].bgColorClass} ${contestConfig[activeTab].textColorClass} border-transparent uppercase`}>
                          {item.category || item.bairro}
                        </span>
                      )}
                    </td>
                    <td className="px-8 py-5 text-sm font-mono font-bold text-slate-400">{item.whatsapp}</td>
                    <td className="px-8 py-5"><div className="flex items-center gap-2 text-[10px] font-black uppercase text-green-500"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>OK</div></td>
                    <td className="px-8 py-5 text-right"><div className="flex items-center justify-end gap-3"><Eye className="w-5 h-5 text-slate-500 hover:text-white" /><button onClick={(e) => deleteOne(e, item.id)} className="p-2 text-slate-500 hover:text-red-500"><Trash2 className="w-5 h-5" /></button></div></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import Header from '../components/Header.tsx';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  CheckCircle2, Music, Send, Star, AlertCircle, Camera, 
  Wand2, Gamepad2, MapPin, Calendar, User, Mail, 
  Phone, Home, Map, RefreshCw, MessageCircle, Clock, 
  Link as LinkIcon, FileText, Award, Mic, Newspaper, Radio, Laptop, Camera as CameraIcon
} from 'lucide-react';

interface LandingPageProps {
  activeContest: ContestType;
  setActiveContest: (type: ContestType) => void;
  onGoAdmin: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ activeContest, setActiveContest, onGoAdmin }) => {
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otherId, setOtherId] = useState('');
  const [selectedIdentifications, setSelectedIdentifications] = useState<string[]>([]);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setSelectedIdentifications([]);
    setOtherId('');
    setError(null);
  }, [activeContest]);

  const handleIdentificationChange = (val: string) => {
    if (selectedIdentifications.includes(val)) {
      setSelectedIdentifications(prev => prev.filter(i => i !== val));
    } else {
      if (selectedIdentifications.length < 3) {
        setSelectedIdentifications(prev => [...prev, val]);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (activeContest === 'arena' && selectedIdentifications.length === 0) {
      setError('Selecione pelo menos uma opção em "Como você se identifica?".');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData(e.currentTarget);
    const rawData = Object.fromEntries(formData.entries());

    let payload: any = { ...rawData };
    const createdAt = new Date().toISOString();

    if (activeContest === 'arena') {
      const finalIdentifications = selectedIdentifications.map(item => {
        if (item === 'Outro:') return `Outro: ${otherId || 'Não especificado'}`;
        return item;
      }).join(', ');

      payload = {
        name: rawData.name,
        email: rawData.email,
        whatsapp: rawData.whatsapp,
        bairro: rawData.bairro,
        city: rawData.city,
        birth_date: rawData.birth_date,
        identification: finalIdentifications,
        created_at: createdAt
      };
    } else if (activeContest === 'imprensa') {
      payload = {
        full_name: rawData.full_name,
        badge_name: rawData.badge_name,
        document: rawData.document,
        whatsapp: rawData.whatsapp,
        email: rawData.email,
        media_outlet: rawData.media_outlet,
        media_type: rawData.media_type,
        role: rawData.role,
        city_state: rawData.city_state,
        link: rawData.link,
        coverage_type: rawData.coverage_type,
        special_credential: rawData.special_credential,
        equipment: rawData.equipment,
        responsibility_term: rawData.responsibility_term === 'on',
        image_release: rawData.image_release === 'on',
        signature: rawData.signature,
        created_at: createdAt
      };
    } else {
      payload.created_at = createdAt;
      const checkboxFields = ['image_release', 'rules_agreement', 'authorship_declaration'];
      checkboxFields.forEach(field => {
        if (payload[field] !== undefined) {
          payload[field] = payload[field] === 'on';
        }
      });
    }

    const tableName = activeContest === 'kpop' ? TABLES.KPOP : 
                     activeContest === 'cospobre' ? TABLES.COSPOBRE : 
                     activeContest === 'arena' ? TABLES.ARENA :
                     activeContest === 'imprensa' ? TABLES.IMPRENSA :
                     TABLES.COSPLAYER;

    try {
      const { error: insertError } = await supabase.from(tableName).insert([payload]);
      if (insertError) throw insertError;
      setSubmitted(true);
    } catch (err: any) {
      console.error("Erro ao inserir:", err);
      setError(err.message || 'Ocorreu um erro ao processar sua inscrição.');
    } finally {
      setLoading(false);
    }
  };

  const getContestVisuals = (type: ContestType) => {
    switch (type) {
      case 'cospobre': return { title: 'Cospobre', color: 'from-green-500', accent: 'green', shadow: 'shadow-green-500/20', focus: 'focus:ring-green-500/50 focus:border-green-500', btn: 'bg-green-600 hover:bg-green-500' };
      case 'cosplayer': return { title: 'Cosplayer', color: 'from-purple-500', accent: 'purple', shadow: 'shadow-purple-500/20', focus: 'focus:ring-purple-500/50 focus:border-purple-500', btn: 'bg-purple-600 hover:bg-purple-500' };
      case 'arena': return { title: 'Arena Gamer', color: 'from-cyan-400', accent: 'cyan', shadow: 'shadow-cyan-500/20', focus: 'focus:ring-cyan-500/50 focus:border-cyan-500', btn: 'bg-cyan-600 hover:bg-cyan-500' };
      case 'imprensa': return { title: 'Imprensa', color: 'from-indigo-500', accent: 'indigo', shadow: 'shadow-indigo-500/20', focus: 'focus:ring-indigo-500/50 focus:border-indigo-500', btn: 'bg-indigo-600 hover:bg-indigo-500' };
      default: return { title: 'K-Pop', color: 'from-pink-500', accent: 'pink', shadow: 'shadow-pink-500/20', focus: 'focus:ring-pink-500/50 focus:border-pink-500', btn: 'bg-pink-600 hover:bg-pink-500' };
    }
  };

  const activeVisuals = getContestVisuals(activeContest);
  const inputStyle = `w-full bg-slate-800/40 border border-slate-700/50 rounded-xl p-3 outline-none text-white transition-all placeholder:text-slate-600 focus:ring-4 ${activeVisuals.focus}`;
  const labelStyle = "text-[10px] font-black text-slate-500 mb-2 block uppercase tracking-[0.15em]";

  const renderFormFields = () => {
    if (activeContest === 'imprensa') {
      return (
        <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-500 relative z-10 text-left">
          <div className="space-y-6">
            <h3 className="text-xs font-black text-indigo-400 uppercase tracking-widest border-b border-indigo-500/20 pb-2 flex items-center gap-2"><User className="w-3 h-3"/> DADOS PESSOAIS</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome Completo *</label>
                <input required name="full_name" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Nome profissional / crachá *</label>
                <input required name="badge_name" type="text" className={inputStyle} />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelStyle}>CPF ou RG *</label>
                <input required name="document" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Telefone / WhatsApp *</label>
                <input required name="whatsapp" type="tel" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>E-mail *</label>
                <input required name="email" type="email" className={inputStyle} />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h3 className="text-xs font-black text-indigo-400 uppercase tracking-widest border-b border-indigo-500/20 pb-2 flex items-center gap-2"><Newspaper className="w-3 h-3"/> DADOS DO VEÍCULO</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome do veículo *</label>
                <input required name="media_outlet" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Tipo de mídia *</label>
                <select required name="media_type" className={inputStyle}>
                  <option value="">Selecione...</option>
                  <option value="TV">TV</option>
                  <option value="Rádio">Rádio</option>
                  <option value="Portal">Portal</option>
                  <option value="Jornal">Jornal</option>
                  <option value="Blog">Blog</option>
                  <option value="Influencer">Influencer</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelStyle}>Cargo / Função *</label>
                <input required name="role" type="text" className={inputStyle} placeholder="Repórter, Fotógrafo..." />
              </div>
              <div>
                <label className={labelStyle}>Cidade / Estado *</label>
                <input required name="city_state" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Link do site ou rede social *</label>
                <input required name="link" type="url" className={inputStyle} placeholder="https://..." />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h3 className="text-xs font-black text-indigo-400 uppercase tracking-widest border-b border-indigo-500/20 pb-2 flex items-center gap-2"><Mic className="w-3 h-3"/> DADOS OPERACIONAIS</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Cobertura: Foto / Vídeo / Entrevista *</label>
                <input required name="coverage_type" type="text" className={inputStyle} placeholder="Ex: Apenas fotos e entrevistas" />
              </div>
              <div>
                <label className={labelStyle}>Necessita credencial especial?</label>
                <select name="special_credential" className={inputStyle}>
                  <option value="Nenhuma">Não necessita</option>
                  <option value="Área VIP">Área VIP</option>
                  <option value="Palco">Acesso ao Palco</option>
                  <option value="Backstage">Backstage</option>
                  <option value="Total">Acesso Total</option>
                </select>
              </div>
            </div>
            <div>
              <label className={labelStyle}>Equipamentos que levará *</label>
              <textarea required name="equipment" rows={2} className={inputStyle} placeholder="Câmeras, tripés, microfones, drones..."></textarea>
            </div>
          </div>
        </div>
      );
    }

    if (activeContest === 'arena') {
      return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500 relative z-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><User className="w-3 h-3"/> Nome Completo *</span></label>
              <input required name="name" type="text" className={inputStyle} placeholder="Como está no documento" />
            </div>
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><Mail className="w-3 h-3"/> E-mail *</span></label>
              <input required name="email" type="email" className={inputStyle} placeholder="seu@email.com" />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><Phone className="w-3 h-3"/> WhatsApp *</span></label>
              <input required name="whatsapp" type="tel" className={inputStyle} placeholder="(00) 00000-0000" />
            </div>
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><Calendar className="w-3 h-3"/> Data de Nascimento *</span></label>
              <input required name="birth_date" type="date" className={inputStyle} />
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><Home className="w-3 h-3"/> Bairro *</span></label>
              <input required name="bairro" type="text" className={inputStyle} placeholder="Seu bairro" />
            </div>
            <div>
              <label className={labelStyle}><span className="flex items-center gap-2"><Map className="w-3 h-3"/> Cidade *</span></label>
              <input required name="city" type="text" className={inputStyle} placeholder="Sua cidade" />
            </div>
          </div>
          <div>
            <div className="flex justify-between items-end mb-2">
              <label className={labelStyle}>Como você se identifica? (Marque até 3) *</label>
              <span className={`text-[9px] font-black uppercase ${selectedIdentifications.length === 3 ? 'text-cyan-400' : 'text-slate-600'}`}>
                {selectedIdentifications.length} / 3 selecionados
              </span>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mt-2">
              {['Gamer', 'Otaku', 'Cosplayer', 'K-pop', 'Entusiasta da cultura Geek', 'Outro:'].map((opt) => {
                const isSelected = selectedIdentifications.includes(opt);
                const isDisabled = !isSelected && selectedIdentifications.length >= 3;
                return (
                  <label key={opt} className={`flex items-center gap-2 p-3 border rounded-xl cursor-pointer transition-all group ${isSelected ? 'bg-cyan-500/10 border-cyan-500/50 ring-1 ring-cyan-500/20' : 'bg-slate-800/30 border-slate-700/50 hover:bg-white/5'} ${isDisabled ? 'opacity-40 cursor-not-allowed' : ''}`}>
                    <input type="checkbox" checked={isSelected} disabled={isDisabled} onChange={() => handleIdentificationChange(opt)} className="w-4 h-4 rounded text-cyan-500 focus:ring-0 bg-slate-700 border-slate-600" />
                    <span className={`text-xs font-bold transition-colors ${isSelected ? 'text-white' : 'text-slate-400 group-hover:text-slate-200'}`}>{opt}</span>
                  </label>
                );
              })}
            </div>
            {selectedIdentifications.includes('Outro:') && (
              <div className="mt-4 animate-in fade-in slide-in-from-top-2">
                <label className={labelStyle}>Especifique sua identificação *</label>
                <input type="text" placeholder="Ex: Desenvolvedor, Streamer..." className={inputStyle} value={otherId} onChange={(e) => setOtherId(e.target.value)} required />
              </div>
            )}
          </div>
        </div>
      );
    }

    if (activeContest === 'kpop') {
      return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome do Grupo / Artista Solo *</label>
              <input required name="group_name" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Categoria *</label>
              <select required name="category" className={inputStyle}>
                <option value="">Selecione...</option>
                <option value="solo">Solo</option>
                <option value="duo">Duo</option>
                <option value="grupo">Grupo</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Nome do Fandom (Se houver)</label>
              <input name="fandom_name" type="text" className={inputStyle} placeholder="Ex: ARMY, Blink..." />
            </div>
            <div>
              <label className={labelStyle}>Estilo de Performance *</label>
              <select required name="performance_style" className={inputStyle}>
                <option value="cover">Cover (Fiel ao original)</option>
                <option value="autoral">Autoral / Remix</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>WhatsApp de Contato *</label>
              <input required name="whatsapp" type="tel" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>E-mail *</label>
              <input required name="email" type="email" className={inputStyle} />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Data de Nascimento (Líder/Solo) *</label>
              <input required name="birth_date" type="date" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Cidade e Estado *</label>
              <input required name="city_state" type="text" className={inputStyle} placeholder="Ex: Belém - PA" />
            </div>
          </div>

          <div className="bg-white/5 p-6 rounded-2xl border border-white/5 space-y-4">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <User className="w-3 h-3" /> Responsável Legal (Para menores de 18 anos)
            </p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome do Responsável</label>
                <input name="guardian_name" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Documento do Responsável (RG/CPF)</label>
                <input name="guardian_document" type="text" className={inputStyle} />
              </div>
            </div>
          </div>

          <div>
            <label className={labelStyle}>Integrantes (Nomes Completos) *</label>
            <textarea required name="members_names" rows={3} className={inputStyle} placeholder="Separe por vírgulas"></textarea>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className={labelStyle}>Idades dos Membros *</label>
              <input required name="members_ages" type="text" className={inputStyle} placeholder="Ex: 15, 18, 20" />
            </div>
            <div>
              <label className={labelStyle}>Qtd no Palco *</label>
              <input required name="members_count" type="number" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Duração da Apresentação *</label>
              <input required name="duration" type="text" className={inputStyle} placeholder="Ex: 4:30" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Música / Artista *</label>
              <input required name="song_artist" type="text" className={inputStyle} />
            </div>
            <div>
              <label className={labelStyle}>Redes Sociais do Grupo (Link)</label>
              <input name="social_links" type="url" className={inputStyle} placeholder="Instagram/TikTok" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={labelStyle}>Link do Vídeo (YouTube/Drive) *</label>
              <input required name="video_link" type="url" className={inputStyle} placeholder="https://..." />
            </div>
            <div>
              <label className={labelStyle}>Necessidades Técnicas</label>
              <input name="technical_needs" type="text" className={inputStyle} placeholder="Microfones, acessórios, etc." />
            </div>
          </div>
        </div>
      );
    }

    const isCosplayer = activeContest === 'cosplayer';
    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className={labelStyle}>Nome do Participante *</label>
            <input required name={isCosplayer ? "full_name" : "cosplayer_name"} type="text" className={inputStyle} />
          </div>
          <div>
            <label className={labelStyle}>Personagem *</label>
            <input required name="character_name" type="text" className={inputStyle} />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className={labelStyle}>WhatsApp *</label>
            <input required name="whatsapp" type="tel" className={inputStyle} />
          </div>
          <div>
            <label className={labelStyle}>Categoria *</label>
            <select required name="category" className={inputStyle}>
              <option value="tradicional">Tradicional</option>
              <option value="desfile">Desfile</option>
              <option value="kids">Kids</option>
            </select>
          </div>
        </div>
        <div>
          <label className={labelStyle}>Link de Referência / Fotos *</label>
          <input required name="photo_links" type="url" className={inputStyle} placeholder="Link do Drive ou Redes Sociais" />
        </div>
        <div>
          <label className={labelStyle}>Descrição curta do Cosplay *</label>
          <textarea required name={isCosplayer ? "description_process" : "cosplay_description"} rows={3} className={inputStyle}></textarea>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-950 min-h-screen text-white pb-20 selection:bg-cyan-500/30 transition-all duration-1000">
      <Header activeContest={activeContest} setActiveContest={setActiveContest} />
      <div className="container mx-auto px-4 pt-20 pb-16 text-center">
        <div className={`inline-flex items-center gap-2 px-5 py-2 rounded-full bg-white/5 border border-white/10 text-slate-400 text-[10px] font-black uppercase tracking-[0.3em] mb-8 animate-in fade-in slide-in-from-top-4 duration-700`}>
           {activeContest === 'arena' ? <Gamepad2 className="w-4 h-4 text-cyan-400"/> : activeContest === 'imprensa' ? <Mic className="w-4 h-4 text-indigo-400"/> : <Star className="w-4 h-4 text-pink-400"/>} GEEKZADA FESTIVAL 2026
        </div>
        <h2 className={`text-6xl md:text-[7rem] font-black bg-clip-text text-transparent bg-gradient-to-b ${activeVisuals.color} to-white uppercase tracking-tighter mb-8 leading-[0.85] animate-in zoom-in-95 duration-500`}>
          {activeContest === 'arena' ? 'ARENA GAMER' : activeContest === 'imprensa' ? 'CREDENCIAMENTO IMPRENSA' : `CONCURSO ${activeVisuals.title}`}
        </h2>
        {activeContest === 'arena' ? (
          <div className="flex flex-wrap items-center justify-center gap-4 mb-16 animate-in duration-1000 delay-300">
            <div className="px-6 py-3 bg-white/5 rounded-2xl border border-white/10 backdrop-blur-sm flex items-center gap-3">
              <Calendar className="w-5 h-5 text-cyan-400" />
              <div className="text-left">
                <p className="text-[9px] text-slate-500 font-black uppercase">Data</p>
                <p className="text-sm font-bold">28 DE FEV</p>
              </div>
            </div>
            <div className="px-6 py-3 bg-white/5 rounded-2xl border border-white/10 backdrop-blur-sm flex items-center gap-3">
              <MapPin className="w-5 h-5 text-cyan-400" />
              <div className="text-left">
                <p className="text-[9px] text-slate-500 font-black uppercase">Local</p>
                <p className="text-sm font-bold">ESTÁDIO MANGUEIRÃO</p>
              </div>
            </div>
          </div>
        ) : activeContest === 'imprensa' ? (
          <div className="mb-16"></div>
        ) : (
          <p className="text-slate-500 max-w-xl mx-auto text-sm md:text-base mb-16 font-medium leading-relaxed italic">
            "A glória espera por aqueles que transformam sua paixão em arte."
          </p>
        )}
      </div>
      <section className="container mx-auto px-4">
        <div className={`max-w-4xl mx-auto bg-slate-900/30 backdrop-blur-3xl border border-white/10 rounded-[3rem] p-8 md:p-16 shadow-2xl transition-all duration-700 relative ${activeVisuals.shadow}`}>
          <form onSubmit={handleSubmit} className="space-y-12 relative z-10">
            {renderFormFields()}

            <div className="space-y-6 pt-12 border-t border-white/5">
              <div className="grid grid-cols-1 gap-4">
                {activeContest === 'imprensa' ? (
                  <>
                    <label className="flex items-start gap-4 cursor-pointer group p-4 bg-white/5 rounded-2xl hover:bg-white/10 transition-colors border border-transparent hover:border-white/5 text-left">
                      <input required name="responsibility_term" type="checkbox" className="w-6 h-6 rounded-md border-slate-700 bg-slate-800 text-white focus:ring-0 mt-1" />
                      <span className="text-xs text-slate-400 group-hover:text-slate-200 transition-colors leading-relaxed font-medium">Declaro assumir total responsabilidade pelo uso de equipamentos e conduta profissional durante o evento.</span>
                    </label>
                    <label className="flex items-start gap-4 cursor-pointer group p-4 bg-white/5 rounded-2xl hover:bg-white/10 transition-colors border border-transparent hover:border-white/5 text-left">
                      <input required name="image_release" type="checkbox" className="w-6 h-6 rounded-md border-slate-700 bg-slate-800 text-white focus:ring-0 mt-1" />
                      <span className="text-xs text-slate-400 group-hover:text-slate-200 transition-colors leading-relaxed font-medium">Autorizo o uso de minha imagem para fins de divulgação do evento Geekzada 2026.</span>
                    </label>
                  </>
                ) : (
                  <>
                    <label className="flex items-start gap-4 cursor-pointer group p-4 bg-white/5 rounded-2xl hover:bg-white/10 transition-colors border border-transparent hover:border-white/5 text-left">
                      <input required name="image_release" type="checkbox" className="w-6 h-6 rounded-md border-slate-700 bg-slate-800 text-white focus:ring-0 mt-1" />
