export enum AppRoute {
  LANDING = 'landing',
  ADMIN_LOGIN = 'admin-login',
  ADMIN_DASHBOARD = 'admin-dashboard'
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = 'https://gnvgfrudfdeslxmvxjxm.supabase.co';
const supabaseKey = 'sb_publishable_wdfQor7-mUD05yt7wOgF9A_CgU7xLzc';

// O cliente é inicializado com persistência básica para funcionar melhor em navegadores mobile
export const supabase = createClient(supabaseUrl, supabaseKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

export const TABLES = {
  KPOP: 'k_registrations',
  COSPOBRE: 'cospobre_registrations',
  COSPLAYER: 'cosplayer_registrations',
  ARENA: 'arena_registrations',
  IMPRENSA: 'press_registrations',
  ESTANDISTA: 'stand_registrations'
};

import React, { useState, useEffect, useCallback } from 'react';
import LandingPage from './pages/LandingPage.tsx';
import AdminLogin from './pages/AdminLogin.tsx';
import AdminDashboard from './pages/AdminDashboard.tsx';
import { AppRoute, ContestType } from './types.ts';

const App: React.FC = () => {
  const [currentRoute, setCurrentRoute] = useState<AppRoute>(AppRoute.LANDING);
  const [activeContest, setActiveContest] = useState<ContestType>('kpop');

  const handleRouteUpdate = useCallback(() => {
    const hash = window.location.hash;
    if (hash.startsWith('#admin')) {
      const isLoggedIn = sessionStorage.getItem('admin_logged_in') === 'true';
      setCurrentRoute(isLoggedIn ? AppRoute.ADMIN_DASHBOARD : AppRoute.ADMIN_LOGIN);
    } else if (hash === '#cospobre') {
      setActiveContest('cospobre');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#cosplayer') {
      setActiveContest('cosplayer');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#arena') {
      setActiveContest('arena');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#imprensa') {
      setActiveContest('imprensa');
      setCurrentRoute(AppRoute.LANDING);
    } else if (hash === '#estandista') {
      setActiveContest('estandista');
      setCurrentRoute(AppRoute.LANDING);
    } else {
      setActiveContest('kpop');
      setCurrentRoute(AppRoute.LANDING);
    }
  }, []);

  useEffect(() => {
    window.addEventListener('hashchange', handleRouteUpdate);
    handleRouteUpdate();

    return () => window.removeEventListener('hashchange', handleRouteUpdate);
  }, [handleRouteUpdate]);

  const navigate = (route: string) => {
    window.location.hash = route;
  };

  const renderContent = () => {
    switch (currentRoute) {
      case AppRoute.ADMIN_LOGIN:
        return (
          <AdminLogin 
            onLogin={() => {
              handleRouteUpdate();
            }} 
          />
        );
      case AppRoute.ADMIN_DASHBOARD:
        return (
          <AdminDashboard 
            onLogout={() => {
              sessionStorage.removeItem('admin_logged_in');
              navigate('');
            }} 
          />
        );
      case AppRoute.LANDING:
      default:
        return (
          <LandingPage 
            activeContest={activeContest} 
            setActiveContest={(type) => navigate(type === 'kpop' ? '' : type)}
            onGoAdmin={() => navigate('admin')} 
          />
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-950">
      {renderContent()}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Header from '../components/Header.tsx';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  CheckCircle2, Music, Send, Star, AlertCircle, Camera, 
  Wand2, Gamepad2, MapPin, Calendar, User, Mail, 
  Phone, Home, Map, RefreshCw, MessageCircle, Clock, 
  Link as LinkIcon, FileText, Award, Mic, Newspaper, Radio, Laptop, 
  Camera as CameraIcon, Store, Briefcase, Zap, Globe, Package
} from 'lucide-react';

interface LandingPageProps {
  activeContest: ContestType;
  setActiveContest: (type: ContestType) => void;
  onGoAdmin: () => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ activeContest, setActiveContest, onGoAdmin }) => {
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otherId, setOtherId] = useState('');
  const [selectedIdentifications, setSelectedIdentifications] = useState<string[]>([]);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setSelectedIdentifications([]);
    setOtherId('');
    setError(null);
  }, [activeContest]);

  const handleIdentificationChange = (val: string) => {
    if (selectedIdentifications.includes(val)) {
      setSelectedIdentifications(prev => prev.filter(i => i !== val));
    } else {
      if (selectedIdentifications.length < 3) {
        setSelectedIdentifications(prev => [...prev, val]);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (activeContest === 'arena' && selectedIdentifications.length === 0) {
      setError('Selecione pelo menos uma opção em "Como você se identifica?".');
      return;
    }

    setLoading(true);
    setError(null);

    const formData = new FormData(e.currentTarget);
    const rawData = Object.fromEntries(formData.entries());

    let payload: any = { ...rawData };
    const createdAt = new Date().toISOString();

    if (activeContest === 'arena') {
      const finalIdentifications = selectedIdentifications.map(item => {
        if (item === 'Outro:') return `Outro: ${otherId || 'Não especificado'}`;
        return item;
      }).join(', ');

      payload = {
        name: rawData.name,
        email: rawData.email,
        whatsapp: rawData.whatsapp,
        bairro: rawData.bairro,
        city: rawData.city,
        birth_date: rawData.birth_date,
        identification: finalIdentifications,
        created_at: createdAt
      };
    } else if (activeContest === 'imprensa') {
      payload = {
        full_name: rawData.full_name,
        badge_name: rawData.badge_name,
        document: rawData.document,
        whatsapp: rawData.whatsapp,
        email: rawData.email,
        media_outlet: rawData.media_outlet,
        media_type: rawData.media_type,
        role: rawData.role,
        city_state: rawData.city_state,
        link: rawData.link,
        coverage_type: rawData.coverage_type,
        special_credential: rawData.special_credential,
        equipment: rawData.equipment,
        responsibility_term: rawData.responsibility_term === 'on',
        image_release: rawData.image_release === 'on',
        signature: rawData.signature,
        created_at: createdAt
      };
    } else if (activeContest === 'estandista') {
      payload = {
        ...rawData,
        rules_agreement: rawData.rules_agreement === 'on',
        created_at: createdAt
      };
    } else {
      payload.created_at = createdAt;
      const checkboxFields = ['image_release', 'rules_agreement', 'authorship_declaration'];
      checkboxFields.forEach(field => {
        if (payload[field] !== undefined) {
          payload[field] = payload[field] === 'on';
        }
      });
    }

    const tableName = activeContest === 'kpop' ? TABLES.KPOP : 
                     activeContest === 'cospobre' ? TABLES.COSPOBRE : 
                     activeContest === 'arena' ? TABLES.ARENA :
                     activeContest === 'imprensa' ? TABLES.IMPRENSA :
                     activeContest === 'estandista' ? TABLES.ESTANDISTA :
                     TABLES.COSPLAYER;

    try {
      const { error: insertError } = await supabase.from(tableName).insert([payload]);
      if (insertError) throw insertError;
      setSubmitted(true);
    } catch (err: any) {
      console.error("Erro ao inserir:", err);
      setError(err.message || 'Ocorreu um erro ao processar sua inscrição.');
    } finally {
      setLoading(false);
    }
  };

  const getContestVisuals = (type: ContestType) => {
    switch (type) {
      case 'cospobre': return { title: 'Cospobre', color: 'from-green-500', accent: 'green', shadow: 'shadow-green-500/20', focus: 'focus:ring-green-500/50 focus:border-green-500', btn: 'bg-green-600 hover:bg-green-500' };
      case 'cosplayer': return { title: 'Cosplayer', color: 'from-purple-500', accent: 'purple', shadow: 'shadow-purple-500/20', focus: 'focus:ring-purple-500/50 focus:border-purple-500', btn: 'bg-purple-600 hover:bg-purple-500' };
      case 'arena': return { title: 'Arena Gamer', color: 'from-cyan-400', accent: 'cyan', shadow: 'shadow-cyan-500/20', focus: 'focus:ring-cyan-500/50 focus:border-cyan-500', btn: 'bg-cyan-600 hover:bg-cyan-500' };
      case 'imprensa': return { title: 'Imprensa', color: 'from-indigo-500', accent: 'indigo', shadow: 'shadow-indigo-500/20', focus: 'focus:ring-indigo-500/50 focus:border-indigo-500', btn: 'bg-indigo-600 hover:bg-indigo-500' };
      case 'estandista': return { title: 'Expositores', color: 'from-orange-500', accent: 'orange', shadow: 'shadow-orange-500/20', focus: 'focus:ring-orange-500/50 focus:border-orange-500', btn: 'bg-orange-600 hover:bg-orange-500' };
      default: return { title: 'K-Pop', color: 'from-pink-500', accent: 'pink', shadow: 'shadow-pink-500/20', focus: 'focus:ring-pink-500/50 focus:border-pink-500', btn: 'bg-pink-600 hover:bg-pink-500' };
    }
  };

  const activeVisuals = getContestVisuals(activeContest);
  const inputStyle = `w-full bg-slate-800/40 border border-slate-700/50 rounded-xl p-3 outline-none text-white transition-all placeholder:text-slate-600 focus:ring-4 ${activeVisuals.focus}`;
  const labelStyle = "text-[10px] font-black text-slate-500 mb-2 block uppercase tracking-[0.15em]";

  const renderFormFields = () => {
    if (activeContest === 'estandista') {
      return (
        <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-500 relative z-10 text-left">
          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2"><Briefcase className="w-3 h-3"/> DADOS DA EMPRESA</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Razão Social *</label>
                <input required name="razao_social" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Nome Fantasia *</label>
                <input required name="nome_fantasia" type="text" className={inputStyle} />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelStyle}>CNPJ *</label>
                <input required name="cnpj" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Cidade / Estado *</label>
                <input required name="city_state" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Segmento de atuação *</label>
                <input required name="segment" type="text" className={inputStyle} />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2"><User className="w-3 h-3"/> RESPONSÁVEL PELO ESTANDE</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome Completo *</label>
                <input required name="responsible_name" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Cargo *</label>
                <input required name="responsible_role" type="text" className={inputStyle} />
