            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div>
                <label className={labelStyle}>Qtd de Pessoas *</label>
                <input required name="team_size" type="number" className={inputStyle} />
              </div>
              <div className="md:col-span-2">
                <label className={labelStyle}>Necessidade Elétrica *</label>
