              </div>
              <div>
                <label className={labelStyle}>Internet? *</label>
                <select required name="internet_need" className={inputStyle}>
                  <option value="Sim">Sim</option>
                  <option value="Não">Não</option>
                </select>
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2"><RefreshCw className="w-3 h-3"/> LOGÍSTICA</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
