          <div className="space-y-6">
            <h3 className="text-xs font-black text-indigo-400 uppercase tracking-widest border-b border-indigo-500/20 pb-2 flex items-center gap-2"><User className="w-3 h-3"/> DADOS PESSOAIS</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome Completo *</label>
                <input required name="full_name" type="text" className={inputStyle} />
