import React, { useState, useEffect, useMemo } from 'react';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  Trash2, LogOut, Search, RefreshCw, FileSpreadsheet, Layers, 
  Music, Wand2, Camera, Link, Copy, Check, ExternalLink, 
  Gamepad2, X, Eye, Calendar, User, Phone, Mail, Info, 
  Share2, TriangleAlert, Mic, ChevronLeft, ChevronRight, Store
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<ContestType>('kpop');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [copiedLink, setCopiedLink] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<any | null>(null);
  const [counts, setCounts] = useState<Record<string, number>>({
    kpop: 0, cospobre: 0, cosplayer: 0, arena: 0, imprensa: 0, estandista: 0
  });

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 100;

  const contestConfig: Record<ContestType, { label: string; icon: any; colorClass: string; bgColorClass: string; textColorClass: string; hash: string }> = {
    kpop: { label: 'K-Pop', icon: Music, colorClass: 'bg-pink-600', bgColorClass: 'bg-pink-500/10', textColorClass: 'text-pink-500', hash: '' },
    cospobre: { label: 'Cospobre', icon: Wand2, colorClass: 'bg-green-600', bgColorClass: 'bg-green-500/10', textColorClass: 'text-green-500', hash: '#cospobre' },
    cosplayer: { label: 'Cosplayer', icon: Camera, colorClass: 'bg-purple-600', bgColorClass: 'bg-purple-500/10', textColorClass: 'text-purple-500', hash: '#cosplayer' },
    arena: { label: 'Arena Gamer', icon: Gamepad2, colorClass: 'bg-cyan-600', bgColorClass: 'bg-cyan-500/10', textColorClass: 'text-cyan-500', hash: '#arena' },
    imprensa: { label: 'Imprensa', icon: Mic, colorClass: 'bg-indigo-600', bgColorClass: 'bg-indigo-500/10', textColorClass: 'text-indigo-500', hash: '#imprensa' },
    estandista: { label: 'Expositores', icon: Store, colorClass: 'bg-orange-600', bgColorClass: 'bg-orange-500/10', textColorClass: 'text-orange-500', hash: '#estandista' }
  };

  const menuItems = (Object.keys(contestConfig) as ContestType[]).map(key => ({
    id: key,
    ...contestConfig[key]
  }));

  const getTableName = (tab: ContestType) => {
    switch (tab) {
      case 'kpop': return TABLES.KPOP;
      case 'cospobre': return TABLES.COSPOBRE;
      case 'cosplayer': return TABLES.COSPLAYER;
      case 'arena': return TABLES.ARENA;
      case 'imprensa': return TABLES.IMPRENSA;
      case 'estandista': return TABLES.ESTANDISTA;
      default: return TABLES.KPOP;
    }
  };

  const fetchCounts = async () => {
    const types = Object.keys(contestConfig) as ContestType[];
    const newCounts: any = { ...counts };

    for (const type of types) {
      try {
        const { count, error } = await supabase
          .from(getTableName(type))
          .select('*', { count: 'exact', head: true });
        if (!error) {
          newCounts[type] = count || 0;
        }
      } catch (err) {
        console.error(`Erro ao contar ${type}:`, err);
      }
    }
    setCounts(newCounts);
  };

  const fetchData = async () => {
    setLoading(true);
    const tableName = getTableName(activeTab);
    try {
      const { data: result, error } = await supabase.from(tableName).select('*').order('created_at', { ascending: false });
      if (error) throw error;
      setData(result || []);

      // Update the specific count for the active tab
      setCounts(prev => ({ ...prev, [activeTab]: result?.length || 0 }));

      setCurrentPage(1); // Reset to first page on tab change
    } catch (err) {
      console.error(err);
      alert('Erro ao carregar dados do banco.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCounts(); // Fetch all counts on mount
    fetchData();
  }, [activeTab]);

  useEffect(() => {
    setCurrentPage(1); // Reset to first page when searching
  }, [searchTerm]);

  const deleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!id) return;

    const confirmMessage = `Tem certeza que deseja excluir permanentemente este registro da categoria ${activeTab.toUpperCase()}?`;
    if (!window.confirm(confirmMessage)) return;

    const tableName = getTableName(activeTab);

    try {
      const { error } = await supabase.from(tableName).delete().eq('id', id);
      if (error) throw error;

      setData(prev => prev.filter(item => item.id !== id));
      setCounts(prev => ({ ...prev, [activeTab]: Math.max(0, prev[activeTab] - 1) }));

      if (selectedItem?.id === id) {
        setSelectedItem(null);
      }
    } catch (err: any) {
      console.error("Erro ao deletar:", err);
      alert('Não foi possível excluir o registro. Verifique sua conexão ou permissões.');
    }
  };

  const deleteAll = async () => {
    if (data.length === 0) return alert('Não há registros para deletar.');
    const count = data.length;
    const confirmation = window.confirm(`⚠️ ATENÇÃO: Você está prestes a deletar TODOS os ${count} registros de ${activeTab.toUpperCase()}!\nEsta ação é irreversível.`);

    if (!confirmation) return;

    setLoading(true);
    const tableName = getTableName(activeTab);

    try {
      const { error } = await supabase.from(tableName).delete().neq('id', '00000000-0000-0000-0000-000000000000');
      if (error) throw error;

      setData([]);
      setCounts(prev => ({ ...prev, [activeTab]: 0 }));
      setSelectedItem(null);
      alert('Categoria limpa com sucesso.');
    } catch (err: any) {
      console.error(err);
      alert('Erro ao limpar categoria.');
    } finally {
      setLoading(false);
    }
  };

  const exportExcel = () => {
    if (data.length === 0) return alert('Não há dados para exportar.');
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, activeTab.toUpperCase());
    XLSX.writeFile(wb, `Export_${activeTab}_Geekzada.xlsx`);
  };

  const copyFormLink = (hash: string, id: string) => {
    const baseUrl = window.location.origin + window.location.pathname;
    const fullUrl = baseUrl + hash;
    navigator.clipboard.writeText(fullUrl);
    setCopiedLink(id);
    setTimeout(() => setCopiedLink(null), 2000);
  };

  const filteredData = useMemo(() => {
    return data.filter(item => 
      JSON.stringify(item).toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [data, searchTerm]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(start, start + itemsPerPage);
  }, [filteredData, currentPage]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

