                      <button onClick={() => copyFormLink(item.hash, item.id)} className="p-2 hover:bg-white/10 rounded-xl text-slate-500 hover:text-white transition-colors" title="Copiar Link">{copiedLink === item.id ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}</button>
