                  <th className="px-8 py-5">Nome / Grupo</th>
                  <th className="px-8 py-5">
                    {activeTab === 'imprensa' ? 'Veículo' : 
                     activeTab === 'arena' ? 'Bairro' : 
                     activeTab === 'estandista' ? 'Nome Fantasia' : 
                     'Categoria'}
                  </th>
