          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2"><Briefcase className="w-3 h-3"/> DADOS DA EMPRESA</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Razão Social *</label>
                <input required name="razao_social" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Nome Fantasia *</label>
                <input required name="nome_fantasia" type="text" className={inputStyle} />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <label className={labelStyle}>CNPJ *</label>
                <input required name="cnpj" type="text" className={inputStyle} />
