              <div>
                <label className={labelStyle}>Cidade / Estado *</label>
                <input required name="city_state" type="text" className={inputStyle} />
              </div>
              <div>
                <label className={labelStyle}>Segmento de atuação *</label>
                <input required name="segment" type="text" className={inputStyle} />
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2"><User className="w-3 h-3"/> RESPONSÁVEL PELO ESTANDE</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelStyle}>Nome Completo *</label>
                <input required name="responsible_name" type="text" className={inputStyle} />
