import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  Trash2, LogOut, Search, RefreshCw, FileSpreadsheet, Layers, 
  Music, Wand2, Camera, Link, Copy, Check, ExternalLink, 
  Gamepad2, X, Eye, Calendar, User, Phone, Mail, Info, 
  Share2, TriangleAlert, Mic, ChevronLeft, ChevronRight, Store, AlertCircle
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<ContestType>('kpop');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [copiedLink, setCopiedLink] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<any | null>(null);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [counts, setCounts] = useState<Record<string, number>>({
    kpop: 0, cospobre: 0, cosplayer: 0, arena: 0, imprensa: 0, estandista: 0
  });

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 100;

  const contestConfig: Record<ContestType, { label: string; icon: any; colorClass: string; bgColorClass: string; textColorClass: string; hash: string }> = {
    kpop: { label: 'K-Pop', icon: Music, colorClass: 'bg-pink-600', bgColorClass: 'bg-pink-500/10', textColorClass: 'text-pink-500', hash: '' },
    cospobre: { label: 'Cospobre', icon: Wand2, colorClass: 'bg-green-600', bgColorClass: 'bg-green-500/10', textColorClass: 'text-green-500', hash: '#cospobre' },
    cosplayer: { label: 'Cosplayer', icon: Camera, colorClass: 'bg-purple-600', bgColorClass: 'bg-purple-500/10', textColorClass: 'text-purple-500', hash: '#cosplayer' },
    arena: { label: 'Arena Gamer', icon: Gamepad2, colorClass: 'bg-cyan-600', bgColorClass: 'bg-cyan-500/10', textColorClass: 'text-cyan-500', hash: '#arena' },
    imprensa: { label: 'Imprensa', icon: Mic, colorClass: 'bg-indigo-600', bgColorClass: 'bg-indigo-500/10', textColorClass: 'text-indigo-500', hash: '#imprensa' },
    estandista: { label: 'Expositores', icon: Store, colorClass: 'bg-orange-600', bgColorClass: 'bg-orange-500/10', textColorClass: 'text-orange-500', hash: '#estandista' }
  };

  const menuItems = (Object.keys(contestConfig) as ContestType[]).map(key => ({
    id: key,
    ...contestConfig[key]
  }));

  const getTableName = useCallback((tab: ContestType) => {
    switch (tab) {
      case 'kpop': return TABLES.KPOP;
      case 'cospobre': return TABLES.COSPOBRE;
      case 'cosplayer': return TABLES.COSPLAYER;
      case 'arena': return TABLES.ARENA;
      case 'imprensa': return TABLES.IMPRENSA;
      case 'estandista': return TABLES.ESTANDISTA;
      default: return TABLES.KPOP;
    }
  }, []);

  const fetchCounts = useCallback(async () => {
    const types = Object.keys(contestConfig) as ContestType[];
    const newCounts: any = {};

    for (const type of types) {
      try {
        const { count, error } = await supabase
          .from(getTableName(type))
          .select('*', { count: 'exact', head: true });

        if (!error) {
          newCounts[type] = count || 0;
        } else {
          console.warn(`Erro ao contar ${type}:`, error.message);
          newCounts[type] = 0;
        }
      } catch (err) {
        newCounts[type] = 0;
      }
    }
    setCounts(prev => ({ ...prev, ...newCounts }));
  }, [getTableName]);

  const fetchData = useCallback(async (tabToFetch: ContestType = activeTab) => {
    setLoading(true);
    setFetchError(null);
    const tableName = getTableName(tabToFetch);

    try {
      console.log(`Buscando dados da tabela: ${tableName}...`);
      const { data: result, error } = await supabase
        .from(tableName)
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        // Fallback caso a coluna created_at não exista ou cause erro
        const { data: fallbackResult, error: fallbackError } = await supabase
          .from(tableName)
          .select('*');

        if (fallbackError) throw fallbackError;
        setData(fallbackResult || []);
        setCounts(prev => ({ ...prev, [tabToFetch]: fallbackResult?.length || 0 }));
      } else {
        setData(result || []);
        setCounts(prev => ({ ...prev, [tabToFetch]: result?.length || 0 }));
      }

      setCurrentPage(1);
    } catch (err: any) {
      console.error("Erro fatal ao buscar dados:", err);
      setFetchError(err.message || 'Erro de conexão com o banco de dados.');
      setData([]);
    } finally {
      setLoading(false);
    }
  }, [activeTab, getTableName]);

  useEffect(() => {
    fetchCounts();
    fetchData(activeTab);
  }, [activeTab, fetchData, fetchCounts]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm]);

  const deleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!id) return;

    if (!window.confirm(`Tem certeza que deseja excluir permanentemente este registro?`)) return;

    const tableName = getTableName(activeTab);
    try {
      const { error } = await supabase.from(tableName).delete().eq('id', id);
      if (error) throw error;

      setData(prev => prev.filter(item => item.id !== id));
      setCounts(prev => ({ ...prev, [activeTab]: Math.max(0, prev[activeTab] - 1) }));
    } catch (err: any) {
      alert('Erro ao excluir: ' + err.message);
    }
  };

  const deleteAll = async () => {
    if (data.length === 0) return alert('Não há registros para deletar.');
    if (!window.confirm(`⚠️ ATENÇÃO: Deletar TODOS os ${data.length} registros de ${activeTab.toUpperCase()}?`)) return;

    setLoading(true);
    try {
      const { error } = await supabase.from(getTableName(activeTab)).delete().neq('id', '00000000-0000-0000-0000-000000000000');
      if (error) throw error;
      setData([]);
      setCounts(prev => ({ ...prev, [activeTab]: 0 }));
    } catch (err: any) {
      alert('Erro ao limpar: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const exportExcel = () => {
    if (data.length === 0) return alert('Não há dados para exportar.');
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, activeTab.toUpperCase());
    XLSX.writeFile(wb, `Export_${activeTab}_Geekzada.xlsx`);
  };

  const copyFormLink = (hash: string, id: string) => {
    const baseUrl = window.location.origin + window.location.pathname;
    const fullUrl = baseUrl + hash;
    navigator.clipboard.writeText(fullUrl);
    setCopiedLink(id);
    setTimeout(() => setCopiedLink(null), 2000);
  };

  const filteredData = useMemo(() => {
    if (!searchTerm) return data;
    const lowerSearch = searchTerm.toLowerCase();
    return data.filter(item => 
      Object.values(item).some(val => 
        String(val).toLowerCase().includes(lowerSearch)
      )
    );
  }, [data, searchTerm]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(start, start + itemsPerPage);
  }, [filteredData, currentPage]);

  const handlePageChange = (newPage: number) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans pb-20">
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-white/10 w-full max-w-2xl max-h-[90vh] rounded-[2rem] shadow-2xl overflow-hidden flex flex-col">
            <div className={`p-6 border-b border-white/5 flex items-center justify-between bg-gradient-to-r ${contestConfig[activeTab].colorClass}/10 to-transparent`}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${contestConfig[activeTab].bgColorClass} ${contestConfig[activeTab].textColorClass}`}><Info className="w-5 h-5" /></div>
                <div>
                  <h3 className="font-black text-white uppercase tracking-tight">Ficha de Inscrição</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{activeTab.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedItem(null)} className="p-2 hover:bg-white/5 rounded-full transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="overflow-y-auto p-8 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-y-6 gap-x-8">
                {Object.entries(selectedItem).map(([key, value]) => {
                  if (key === 'id' || key === 'created_at') return null;
                  return (
                    <div key={key} className="space-y-1">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{key.replace(/_/g, ' ')}</p>
                      <div className="text-sm font-medium text-slate-200 bg-white/5 p-3 rounded-xl border border-white/5 break-words">
                        {typeof value === 'boolean' ? (value ? '✅ Sim' : '❌ Não') : (value?.toString() || '-')}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      <nav className="bg-slate-900 border-b border-white/5 p-4 sticky top-0 z-50 shadow-xl">
        <div className="container mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <Layers className="text-pink-500 w-6 h-6" />
            <h1 className="font-black text-xl uppercase tracking-tighter">Admin Geekzada</h1>
          </div>
          <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-800 text-slate-400 border border-white/5 hover:bg-red-600/20 transition-all">
            <span className="text-sm font-bold">SAIR</span><LogOut className="w-4 h-4" />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">
        <div className="mb-10 bg-slate-900/30 p-8 rounded-[2.5rem] border border-white/5 shadow-2xl backdrop-blur-md">
           <div className="flex items-center justify-between mb-8">
             <div className="flex items-center gap-3"><Link className="w-4 h-4 text-pink-500" /><p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">Links dos Formulários</p></div>
             <button onClick={() => { fetchCounts(); fetchData(); }} className="p-2 hover:bg-white/5 rounded-full text-slate-500 hover:text-white transition-all flex items-center gap-2 text-[10px] font-black uppercase tracking-widest">
                <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Atualizar Geral
             </button>
           </div>
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
              {menuItems.map((item) => (
                <div key={item.id} className={`bg-slate-900/60 border ${activeTab === item.id ? 'border-pink-500/50' : 'border-white/5'} p-6 rounded-[2rem] flex flex-col gap-5 group hover:border-pink-500/30 hover:bg-slate-900/80 transition-all shadow-xl`}>
                  <div className="flex items-center justify-between">
                    <div className={`p-3 rounded-2xl shrink-0 ${item.bgColorClass} ${item.textColorClass}`}><item.icon className="w-5 h-5" /></div>
                    <div className="flex items-center gap-0.5 opacity-40 group-hover:opacity-100 transition-opacity">
                      <a href={`${window.location.origin}${window.location.pathname}${item.hash}`} target="_blank" className="p-2 hover:bg-white/10 rounded-xl text-slate-500 hover:text-white transition-colors"><ExternalLink className="w-4 h-4" /></a>
                      <button onClick={() => copyFormLink(item.hash, item.id)} className="p-2 hover:bg-white/10 rounded-xl text-slate-500 hover:text-white transition-colors">{copiedLink === item.id ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}</button>
                    </div>
                  </div>
                  <div className="space-y-1">
                    <span className="text-[10px] font-black uppercase text-slate-500 tracking-[0.15em] block">{item.label}</span>
                    <div className="flex items-baseline gap-2">
                      <span className={`text-3xl font-black ${item.textColorClass} tracking-tighter`}>{counts[item.id] || 0}</span>
                      <span className="text-[9px] font-black uppercase text-slate-600 tracking-widest">Inscrições</span>
                    </div>
                  </div>
                </div>
              ))}
           </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-6 mb-8 items-center justify-between">
          <div className="flex flex-wrap justify-center items-center bg-slate-900 p-1.5 rounded-full border border-white/5 shadow-inner">
            {menuItems.map((item) => (
              <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black transition-all ${activeTab === item.id ? `${item.colorClass} text-white shadow-lg` : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>
                <item.icon className="w-3.5 h-3.5" /><span>{item.label.toUpperCase()}</span>
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 w-full lg:w-auto justify-center">
            <div className="relative flex-1 min-w-[200px] lg:w-64">
              <Search className="absolute left-3 top-3 w-4 h-4 text-slate-500" />
              <input placeholder="Filtrar nesta aba..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-900 border border-white/5 rounded-xl pl-10 pr-4 py-2.5 text-sm outline-none focus:ring-1 focus:ring-white/20" />
            </div>
            <button onClick={exportExcel} className="bg-green-600 hover:bg-green-500 px-4 py-2.5 rounded-xl flex items-center gap-2 text-white font-black uppercase text-xs shadow-lg transition-all"><FileSpreadsheet className="w-4 h-4" />Exportar</button>
            <button onClick={deleteAll} className="bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-500/20 px-4 py-2.5 rounded-xl flex items-center gap-2 font-black uppercase text-xs shadow-lg transition-all"><Trash2 className="w-4 h-4" />Limpar</button>
          </div>
        </div>

        {fetchError && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-2xl flex items-center gap-3 text-red-500 animate-pulse">
            <AlertCircle className="w-5 h-5 shrink-0" />
            <p className="text-xs font-bold uppercase tracking-tight">Erro ao carregar {activeTab}: {fetchError}</p>
          </div>
        )}

        <div className="bg-slate-900/50 rounded-[2.5rem] border border-white/5 overflow-hidden shadow-2xl flex flex-col">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white/5 text-slate-500 text-[10px] uppercase font-black tracking-[0.2em]">
                  <th className="px-8 py-5">Nome / Grupo</th>
                  <th className="px-8 py-5">
                    {activeTab === 'imprensa' ? 'Veículo' : 
                     activeTab === 'arena' ? 'Bairro' : 
                     activeTab === 'estandista' ? 'Nome Fantasia' : 
                     'Categoria'}
                  </th>
                  <th className="px-8 py-5">WhatsApp</th>
                  <th className="px-8 py-5">Status</th>
                  <th className="px-8 py-5 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {loading ? (
                  <tr><td colSpan={5} className="p-32 text-center"><RefreshCw className="animate-spin mx-auto w-10 h-10 text-pink-500" /></td></tr>
                ) : paginatedData.length === 0 ? (
                  <tr><td colSpan={5} className="p-24 text-center text-slate-500 font-bold uppercase tracking-widest opacity-50">Nenhuma inscrição encontrada</td></tr>
                ) : paginatedData.map(item => (
                  <tr key={item.id} onClick={() => setSelectedItem(item)} className="hover:bg-white/[0.03] cursor-pointer transition-all group">
                    <td className="px-8 py-5">
                      <div className="font-black text-white group-hover:text-pink-400 transition-colors uppercase tracking-tight">
                        {activeTab === 'imprensa' ? item.full_name : 
                         activeTab === 'estandista' ? item.razao_social : 
                         (item.group_name || item.cosplayer_name || item.full_name || item.name || 'Sem nome')}
                      </div>
                      <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">
                        {activeTab === 'imprensa' ? (item.badge_name || 'Imprensa') : 
                         activeTab === 'estandista' ? (item.responsible_name || 'Expositor') : 
                         (item.character_name || item.song_artist || item.email || '-')}
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <span className={`text-[10px] font-black px-3 py-1.5 rounded-full border ${contestConfig[activeTab].bgColorClass} ${contestConfig[activeTab].textColorClass} border-transparent uppercase`}>
                        {activeTab === 'imprensa' ? item.media_outlet : 
                         activeTab === 'estandista' ? item.nome_fantasia : 
                         (item.category || item.bairro || 'Geral')}
                      </span>
                    </td>
                    <td className="px-8 py-5 text-sm font-mono font-bold text-slate-400">{item.whatsapp || '-'}</td>
                    <td className="px-8 py-5"><div className="flex items-center gap-2 text-[10px] font-black uppercase text-green-500"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>Recebida</div></td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex items-center justify-end gap-3">
                        <button className="p-2 text-slate-500 hover:text-white hover:bg-white/5 rounded-xl transition-all">
                          <Eye className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={(e) => deleteOne(e, item.id)} 
                          className="p-2 text-slate-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl transition-all"
                        >
                          <Trash2 className="w-5 h-5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination Controls */}
          {!loading && filteredData.length > itemsPerPage && (
            <div className="px-8 py-6 border-t border-white/5 bg-slate-900/40 flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                Exibindo <span className="text-white">{(currentPage - 1) * itemsPerPage + 1} - {Math.min(currentPage * itemsPerPage, filteredData.length)}</span> de <span className="text-white">{filteredData.length}</span> registros
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                  className="p-2 rounded-xl bg-slate-800 text-slate-400 border border-white/5 hover:text-white hover:bg-slate-700 disabled:opacity-30 transition-all"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
                <div className="flex items-center gap-1">
                  {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                    let pageNum = i + 1;
                    return (
                      <button
                        key={pageNum}
                        onClick={() => handlePageChange(pageNum)}
                        className={`w-10 h-10 rounded-xl text-xs font-black transition-all ${currentPage === pageNum ? `${contestConfig[activeTab].colorClass} text-white` : 'bg-slate-800 text-slate-500 border border-white/5 hover:text-white'}`}
                      >
                        {pageNum}
                      </button>
                    );
                  })}
                </div>
                <button 
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                  className="p-2 rounded-xl bg-slate-800 text-slate-400 border border-white/5 hover:text-white hover:bg-slate-700 disabled:opacity-30 transition-all"
                >
                  <ChevronRight className="w-5 h-5" />
                </button>
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="py-12 text-center text-slate-800 text-[10px] font-black uppercase tracking-[0.5em] opacity-30">
        WD SOLUÇÕES DIGITAIS 2026
      </footer>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { supabase, TABLES } from '../supabaseClient.ts';
import { ContestType } from '../types.ts';
import { 
  Trash2, LogOut, Search, RefreshCw, FileSpreadsheet, Layers, 
  Music, Wand2, Camera, Link, Copy, Check, ExternalLink, 
  Gamepad2, X, Eye, Calendar, User, Phone, Mail, Info, 
  Share2, TriangleAlert, Mic, ChevronLeft, ChevronRight, Store, AlertCircle
} from 'lucide-react';
import * as XLSX from 'xlsx';

interface AdminDashboardProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<ContestType>('kpop');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [copiedLink, setCopiedLink] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<any | null>(null);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [counts, setCounts] = useState<Record<string, number>>({
    kpop: 0, cospobre: 0, cosplayer: 0, arena: 0, imprensa: 0, estandista: 0
  });

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 50;

  const contestConfig: Record<ContestType, { label: string; icon: any; colorClass: string; bgColorClass: string; textColorClass: string; hash: string }> = {
    kpop: { label: 'K-Pop', icon: Music, colorClass: 'bg-pink-600', bgColorClass: 'bg-pink-500/10', textColorClass: 'text-pink-500', hash: '' },
    cospobre: { label: 'Cospobre', icon: Wand2, colorClass: 'bg-green-600', bgColorClass: 'bg-green-500/10', textColorClass: 'text-green-500', hash: '#cospobre' },
    cosplayer: { label: 'Cosplayer', icon: Camera, colorClass: 'bg-purple-600', bgColorClass: 'bg-purple-500/10', textColorClass: 'text-purple-500', hash: '#cosplayer' },
    arena: { label: 'Arena Gamer', icon: Gamepad2, colorClass: 'bg-cyan-600', bgColorClass: 'bg-cyan-500/10', textColorClass: 'text-cyan-500', hash: '#arena' },
    imprensa: { label: 'Imprensa', icon: Mic, colorClass: 'bg-indigo-600', bgColorClass: 'bg-indigo-500/10', textColorClass: 'text-indigo-500', hash: '#imprensa' },
    estandista: { label: 'Expositores', icon: Store, colorClass: 'bg-orange-600', bgColorClass: 'bg-orange-500/10', textColorClass: 'text-orange-500', hash: '#estandista' }
  };

  const menuItems = (Object.keys(contestConfig) as ContestType[]).map(key => ({
    id: key,
    ...contestConfig[key]
  }));

  const getTableName = useCallback((tab: ContestType) => {
    switch (tab) {
      case 'kpop': return TABLES.KPOP;
      case 'cospobre': return TABLES.COSPOBRE;
      case 'cosplayer': return TABLES.COSPLAYER;
      case 'arena': return TABLES.ARENA;
      case 'imprensa': return TABLES.IMPRENSA;
      case 'estandista': return TABLES.ESTANDISTA;
      default: return TABLES.KPOP;
    }
  }, []);

  const loadAllCounts = useCallback(async () => {
    const types = Object.keys(contestConfig) as ContestType[];
    const results = await Promise.all(
      types.map(async (type) => {
        const { count, error } = await supabase
          .from(getTableName(type))
          .select('*', { count: 'exact', head: true });
        return { type, count: error ? 0 : (count || 0) };
      })
    );

    const newCounts: any = {};
    results.forEach(r => newCounts[r.type] = r.count);
    setCounts(newCounts);
  }, [getTableName]);

  const fetchData = useCallback(async (tabToFetch: ContestType = activeTab) => {
    setLoading(true);
    setFetchError(null);
    const tableName = getTableName(tabToFetch);

    try {
      const { data: result, error } = await supabase
        .from(tableName)
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        // Fallback simples sem ordenação caso falte a coluna created_at
        const { data: fallbackResult, error: fallbackError } = await supabase
          .from(tableName)
          .select('*');

        if (fallbackError) throw fallbackError;
        setData(fallbackResult || []);
      } else {
        setData(result || []);
      }

      // Atualiza também o contador específico desta aba para garantir sincronia
      loadAllCounts();
      setCurrentPage(1);
    } catch (err: any) {
      console.error("Erro ao buscar registros:", err);
      setFetchError(err.message || 'Erro de conexão.');
      setData([]);
    } finally {
      setLoading(false);
    }
  }, [activeTab, getTableName, loadAllCounts]);

  useEffect(() => {
    fetchData(activeTab);
  }, [activeTab, fetchData]);

  const deleteOne = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm(`Excluir permanentemente este registro?`)) return;

    try {
      const { error } = await supabase.from(getTableName(activeTab)).delete().eq('id', id);
      if (error) throw error;
      fetchData(activeTab);
    } catch (err: any) {
      alert('Erro: ' + err.message);
    }
  };

  const deleteAll = async () => {
    if (!window.confirm(`⚠️ Deletar TODOS os registros de ${activeTab.toUpperCase()}?`)) return;
    try {
      const { error } = await supabase.from(getTableName(activeTab)).delete().neq('id', '0');
      if (error) throw error;
      fetchData(activeTab);
    } catch (err: any) {
      alert('Erro: ' + err.message);
    }
  };

  const exportExcel = () => {
    if (data.length === 0) return alert('Sem dados.');
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, activeTab.toUpperCase());
    XLSX.writeFile(wb, `Geekzada_${activeTab}.xlsx`);
  };

  const copyFormLink = (hash: string, id: string) => {
    const fullUrl = window.location.origin + window.location.pathname + hash;
    navigator.clipboard.writeText(fullUrl);
    setCopiedLink(id);
    setTimeout(() => setCopiedLink(null), 2000);
  };

  const filteredData = useMemo(() => {
    if (!searchTerm) return data;
    const s = searchTerm.toLowerCase();
    return data.filter(item => 
      Object.values(item).some(v => String(v).toLowerCase().includes(s))
    );
  }, [data, searchTerm]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(start, start + itemsPerPage);
  }, [filteredData, currentPage]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans pb-20">
      {/* Detalhes do Registro (Modal) */}
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm" onClick={() => setSelectedItem(null)}>
          <div className="bg-slate-900 border border-white/10 w-full max-w-2xl max-h-[90vh] rounded-[2rem] shadow-2xl overflow-hidden flex flex-col" onClick={e => e.stopPropagation()}>
            <div className={`p-6 border-b border-white/5 flex items-center justify-between bg-gradient-to-r ${contestConfig[activeTab].colorClass}/10 to-transparent`}>
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${contestConfig[activeTab].bgColorClass} ${contestConfig[activeTab].textColorClass}`}><Info className="w-5 h-5" /></div>
                <div>
                  <h3 className="font-black text-white uppercase tracking-tight">Ficha de Inscrição</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{activeTab.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedItem(null)} className="p-2 hover:bg-white/5 rounded-full transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="overflow-y-auto p-8 custom-scrollbar space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {Object.entries(selectedItem).map(([key, value]) => {
                  if (key === 'id' || key === 'created_at') return null;
                  return (
                    <div key={key} className="space-y-1">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{key.replace(/_/g, ' ')}</p>
                      <div className="text-sm font-medium text-slate-200 bg-white/5 p-3 rounded-xl border border-white/5 break-words">
                        {typeof value === 'boolean' ? (value ? '✅ Sim' : '❌ Não') : (String(value) || '-')}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      <nav className="bg-slate-900 border-b border-white/5 p-4 sticky top-0 z-50 shadow-xl">
        <div className="container mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <Layers className="text-pink-500 w-6 h-6" />
            <h1 className="font-black text-xl uppercase tracking-tighter">Admin Geekzada</h1>
          </div>
          <button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-800 text-slate-400 border border-white/5 hover:bg-red-600/20 transition-all">
            <span className="text-sm font-bold uppercase">Sair</span><LogOut className="w-4 h-4" />
          </button>
        </div>
      </nav>

      <main className="container mx-auto px-4 py-8">
        {/* Cards de Contagem */}
        <div className="mb-10 bg-slate-900/30 p-8 rounded-[2.5rem] border border-white/5 shadow-2xl backdrop-blur-md">
           <div className="flex items-center justify-between mb-8">
             <div className="flex items-center gap-3"><Link className="w-4 h-4 text-pink-500" /><p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">Resumo das Inscrições</p></div>
             <button onClick={() => fetchData(activeTab)} className="p-2 hover:bg-white/5 rounded-full text-slate-500 hover:text-white transition-all flex items-center gap-2 text-[10px] font-black uppercase tracking-widest">
                <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Atualizar
             </button>
           </div>
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6">
              {menuItems.map((item) => (
                <div key={item.id} onClick={() => setActiveTab(item.id)} className={`bg-slate-900/60 border ${activeTab === item.id ? 'border-pink-500' : 'border-white/5'} p-6 rounded-[2rem] flex flex-col gap-5 group hover:border-pink-500/30 cursor-pointer hover:bg-slate-900/80 transition-all shadow-xl`}>
                  <div className="flex items-center justify-between">
                    <div className={`p-3 rounded-2xl shrink-0 ${item.bgColorClass} ${item.textColorClass}`}><item.icon className="w-5 h-5" /></div>
                    <button onClick={(e) => { e.stopPropagation(); copyFormLink(item.hash, item.id); }} className="p-2 hover:bg-white/10 rounded-xl text-slate-500 hover:text-white transition-colors">
                      {copiedLink === item.id ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                    </button>
                  </div>
                  <div className="space-y-1">
                    <span className="text-[10px] font-black uppercase text-slate-500 tracking-[0.15em] block">{item.label}</span>
                    <div className="flex items-baseline gap-2">
                      <span className={`text-3xl font-black ${item.textColorClass} tracking-tighter`}>{counts[item.id] || 0}</span>
                      <span className="text-[9px] font-black uppercase text-slate-600 tracking-widest italic">Inscrições</span>
                    </div>
                  </div>
                </div>
              ))}
           </div>
        </div>

        {/* Barra de Filtros */}
        <div className="flex flex-col lg:flex-row gap-6 mb-8 items-center justify-between">
          <div className="flex flex-wrap justify-center items-center bg-slate-900 p-1.5 rounded-full border border-white/5 shadow-inner">
            {menuItems.map((item) => (
              <button key={item.id} onClick={() => setActiveTab(item.id)} className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black transition-all ${activeTab === item.id ? `${item.colorClass} text-white shadow-lg` : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>
                <item.icon className="w-3.5 h-3.5" /><span>{item.label.toUpperCase()}</span>
              </button>
            ))}
          </div>
          <div className="flex flex-wrap gap-2 w-full lg:w-auto justify-center">
            <div className="relative flex-1 min-w-[200px] lg:w-64">
              <Search className="absolute left-3 top-3 w-4 h-4 text-slate-500" />
              <input placeholder="Filtrar nesta lista..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-900 border border-white/5 rounded-xl pl-10 pr-4 py-2.5 text-sm outline-none focus:ring-1 focus:ring-white/20" />
            </div>
            <button onClick={exportExcel} className="bg-green-600 hover:bg-green-500 px-4 py-2.5 rounded-xl flex items-center gap-2 text-white font-black uppercase text-xs shadow-lg transition-all"><FileSpreadsheet className="w-4 h-4" />Exportar</button>
            <button onClick={deleteAll} className="bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-500/20 px-4 py-2.5 rounded-xl flex items-center gap-2 font-black uppercase text-xs shadow-lg transition-all"><Trash2 className="w-4 h-4" />Limpar</button>
          </div>
        </div>

        {fetchError && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-2xl flex items-center gap-3 text-red-500">
            <AlertCircle className="w-5 h-5" />
            <p className="text-xs font-bold uppercase">Erro ao carregar {activeTab}: {fetchError}</p>
