                  <tr><td colSpan={5} className="p-32 text-center"><RefreshCw className="animate-spin mx-auto w-10 h-10 text-pink-500" /></td></tr>
                ) : paginatedData.length === 0 ? (
                  <tr><td colSpan={5} className="p-24 text-center text-slate-500 font-bold uppercase tracking-widest opacity-50 italic">Nenhum registro encontrado em {activeTab}</td></tr>
