      case 'cosplayer': return { title: 'Cosplayer', color: 'from-purple-500', accent: 'purple', shadow: 'shadow-purple-500/20', focus: 'focus:ring-purple-500/50 focus:border-purple-500', btn: 'bg-purple-600 hover:bg-purple-500', textColorClass: 'text-purple-500' };
